def dehydrate_time(value):
    """Dehydrator for `time` values.

    Converts a :class:`datetime.time` instance into a JSON‑serialisable
    representation (ISO 8601 string).  ``None`` is passed through unchanged.
    Raises :class:`TypeError` if the input is not a ``datetime.time`` instance.

    :param value: The value to dehydrate.
    :type value: datetime.time or None
    :return: ISO 8601 string representation of the time, or ``None``.
    :rtype: str or None
    """
    if value is None:
        return None
    try:
        import datetime
    except Exception as exc:
        raise RuntimeError("datetime module is required for dehydrate_time") from exc
    if not isinstance(value, datetime.time):
        raise TypeError(f"dehydrate_time expects a datetime.time instance, got {type(value).__name__}")
    return value.isoformat()

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if value is None:
        raise ValueError("value cannot be None")
    # Handle tuple or list representations
    if isinstance(value, (tuple, list)):
        if len(value) == 2:
            return {'x': value[0], 'y': value[1]}
        elif len(value) == 3:
            return {'x': value[0], 'y': value[1], 'z': value[2]}
        else:
            raise ValueError("tuple/list must have 2 or 3 elements")
    # Handle dict representations
    if isinstance(value, dict):
        if 'x' in value and 'y' in value:
            result = {'x': value['x'], 'y': value['y']}
            if 'z' in value:
                result['z'] = value['z']
            return result
        else:
            raise TypeError("dict must contain 'x' and 'y' keys")
    # Handle objects with attributes
    try:
        x = getattr(value, 'x')
        y = getattr(value, 'y')
    except AttributeError:
        raise TypeError("value must have 'x' and 'y' attributes")
    result = {'x': x, 'y': y}
    if hasattr(value, 'z'):
        result['z'] = getattr(value, 'z')
    return result

def keys(self):
    """Return the keys of the record.

    :return: list of key names
    """
    try:
        # Attempt to retrieve keys from the underlying data structure.
        return list(self._data.keys())
    except AttributeError:
        # If the record has no _data attribute, return an empty list.
        return []
    except Exception as exc:
        # Wrap any other exception in a RuntimeError for clarity.
        raise RuntimeError(f"Failed to retrieve keys: {exc}") from exc

def index(self, key):
    """Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    try:
        seq = getattr(self, 'data', None)
        if seq is None:
            seq = getattr(self, 'items', None)
        if seq is None:
            raise AttributeError("No sequence attribute found")
        if isinstance(seq, dict):
            keys = list(seq.keys())
            return keys.index(key)
        else:
            return seq.index(key)
    except ValueError:
        raise KeyError(f"Key {key!r} not found")
    except AttributeError as e:
        raise AttributeError(f"Cannot find index: {e}")
    except TypeError:
        raise TypeError("Underlying data is not indexable")
    except Exception as e:
        raise RuntimeError(f"Unexpected error: {e}")

def values(self, *keys):
    """
    Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # Retrieve the underlying data structure
    try:
        data = self._data
    except AttributeError:
        raise AttributeError("Record object missing '_data' attribute")

    # Ensure the data is a mapping (dict-like)
    if not isinstance(data, dict):
        raise TypeError(f"Record data must be a dict, got {type(data).__name__}")

    # If no keys are specified, return all values
    if not keys:
        return list(data.values())

    # Prepare a list of items to support index-based access
    items = list(data.items())

    result = []
    for key in keys:
        if isinstance(key, int):
            # Index-based access
            try:
                value = items[key][1]
            except IndexError:
                raise IndexError(f"Index {key} out of range for record of length {len(items)}")
            result.append(value)
        elif isinstance(key, str):
            # Key-based access
            if key not in data:
                raise KeyError(f"Key '{key}' not found in record")
            result.append(data[key])
        else:
            raise TypeError(f"Unsupported key type: {type(key).__name__}")
    return result

def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Ensure the record has the expected attributes
    if not hasattr(self, "_keys") or not hasattr(self, "_values"):
        raise AttributeError("Record object missing required attributes")
    keys_seq = self._keys
    values_seq = self._values
    if len(keys_seq) != len(values_seq):
        raise ValueError("Record keys and values length mismatch")
    # If no keys specified, return all items
    if not keys:
        return dict(zip(keys_seq, values_seq))
    result = {}
    for k in keys:
        if isinstance(k, int):
            # Handle negative indices and bounds checking
            if k < -len(values_seq) or k >= len(values_seq):
                raise IndexError(f"Index {k} out of bounds")
            key_name = keys_seq[k]
            result[key_name] = values_seq[k]
        else:
            # Treat as a key name
            if k in keys_seq:
                idx = keys_seq.index(k)
                result[k] = values_seq[idx]
            else:
                result[k] = None
    return result

def discard(self, n=-1, qid=-1, dehydration_hooks=None,
                hydration_hooks=None, **handlers):
    """
    Appends a DISCARD message to the output queue.

    :param n: number of records to discard, default = -1 (ALL)
    :param qid: query ID to discard for, default = -1 (last query)
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    """
    # Validate parameters
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n < -1:
        raise ValueError("n must be >= -1")
    if not isinstance(qid, int):
        raise TypeError("qid must be an integer")
    if qid < -1:
        raise ValueError("qid must be >= -1")

    # Normalise hooks
    if dehydration_hooks is None:
        dehydration_hooks = {}
    elif not isinstance(dehydration_hooks, dict):
        raise TypeError("dehydration_hooks must be a dict")
    if hydration_hooks is None:
        hydration_hooks = {}
    elif not isinstance(hydration_hooks, dict):
        raise TypeError("hydration_hooks must be a dict")

    # Build the DISCARD message (Bolt protocol message type 0x0B)
    try:
        # The message format is [0x0B, n, qid]
        message = [0x0B, n, qid]
        # Pack the message using the packstream implementation
        packed = self._packstream.pack(message, dehydration_hooks)
    except Exception as exc:
        raise RuntimeError(f"Failed to pack DISCARD message: {exc}") from exc

    # Append the packed message to the output queue
    try:
        self._output_queue.append(packed)
    except AttributeError as exc:
        raise RuntimeError("Output queue not available") from exc

    # Create and return a Response object
    try:
        # Pass handlers as keyword arguments and hydration hooks
        response = self._response_class(**handlers, hydration_hooks=hydration_hooks)
    except Exception as exc:
        raise RuntimeError(f"Failed to create Response: {exc}") from exc

    return response

def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
          db=None, imp_user=None, dehydration_hooks=None,
          hydration_hooks=None, **handlers):
    """
    Appends a BEGIN message to the output queue.

    :param mode: access mode for routing - "READ" or "WRITE" (default)
    :param bookmarks: iterable of bookmark values after which this transaction should begin
    :param metadata: custom metadata dictionary to attach to the transaction
    :param timeout: timeout for transaction execution (seconds)
    :param db: name of the database against which to begin the transaction
        Requires Bolt 4.0+.
    :param imp_user: the user to impersonate
        Requires Bolt 4.4+
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    :return: Response object
    """
    # Validate mode
    if mode not in (None, "READ", "WRITE"):
        raise ValueError("mode must be 'READ', 'WRITE', or None")

    # Validate bookmarks
    if bookmarks is not None:
        try:
            iter(bookmarks)
        except TypeError:
            raise TypeError("bookmarks must be an iterable")
        for b in bookmarks:
            if not isinstance(b, str):
                raise TypeError("each bookmark must be a string")

    # Validate metadata
    if metadata is not None and not isinstance(metadata, dict):
        raise TypeError("metadata must be a dictionary")

    # Validate timeout
    if timeout is not None and not isinstance(timeout, (int, float)):
        raise TypeError("timeout must be a number")

    # Validate db
    if db is not None and not isinstance(db, str):
        raise TypeError("db must be a string")

    # Validate imp_user
    if imp_user is not None and not isinstance(imp_user, str):
        raise TypeError("imp_user must be a string")

    # Validate dehydration_hooks
    if dehydration_hooks is not None and not isinstance(dehydration_hooks, dict):
        raise TypeError("dehydration_hooks must be a dictionary")

    # Validate hydration_hooks
    if hydration_hooks is not None and not isinstance(hydration_hooks, dict):
        raise TypeError("hydration_hooks must be a dictionary")

    # Build the BEGIN message
    message = {"type": "BEGIN"}
    if mode is not None:
        message["mode"] = mode
    if bookmarks is not None:
        message["bookmarks"] = list(bookmarks)
    if metadata is not None:
        message["metadata"] = metadata
    if timeout is not None:
        message["timeout"] = timeout
    if db is not None:
        message["db"] = db
    if imp_user is not None:
        message["imp_user"] = imp_user

    # Append to the output queue
    try:
        self._output_queue.append(message)
    except AttributeError:
        # Fallback if the attribute name differs
        if hasattr(self, "output_queue"):
            self.output_queue.append(message)
        else:
            raise RuntimeError("No output queue available to append the BEGIN message")

    # Return a Response object
    return Response(self, handlers, dehydration_hooks, hydration_hooks)

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    # Validate name
    if not isinstance(name, str):
        raise TypeError(f"name must be a string, got {type(name).__name__}")
    # Validate fields
    if fields is None:
        fields = []
    try:
        iter(fields)
    except TypeError:
        raise TypeError(f"fields must be an iterable of strings, got {type(fields).__name__}")
    field_list = []
    for f in fields:
        if not isinstance(f, str):
            raise TypeError(f"field names must be strings, got {type(f).__name__}")
        field_list.append(f)
    # Validate srid_map
    if srid_map is None:
        srid_map = {}
    if not isinstance(srid_map, dict):
        raise TypeError(f"srid_map must be a dict, got {type(srid_map).__name__}")

    # Define the __init__ method for the new class
    def __init__(self, x, y, srid=None, **kwargs):
        self.x = x
        self.y = y
        if srid is not None:
            if srid not in srid_map:
                raise ValueError(f"SRID {srid} not found in srid_map")
        self.srid = srid
        # Set field attributes
        for field in field_list:
            setattr(self, field, kwargs.get(field, None))
        # Store any extra kwargs as attributes (optional)
        for key, value in kwargs.items():
            if key not in field_list:
                setattr(self, key, value)

    # Define a representation method
    def __repr__(self):
        attrs = [f"x={self.x!r}", f"y={self.y!r}", f"srid={self.srid!r}"]
        for field in field_list:
            attrs.append(f"{field}={getattr(self, field)!r}")
        return f"{name}(" + ", ".join(attrs) + ")"

    # Define a method to get SRID name if available
    def srid_name(self):
        return srid_map.get(self.srid)

    # Build the class dictionary
    class_dict = {
        "__init__": __init__,
        "__repr__": __repr__,
        "srid_name": srid_name,
        "_fields": field_list,
        "_srid_map": srid_map,
        "__module__": __name__,
    }

    # Create and return the new class
    return type(name, (object,), class_dict)

def deprecated(message):
    if not isinstance(message, str):
        raise TypeError("message must be a string")
    def decorator(func):
        wraps = __import__('functools').wraps
        @wraps(func)
        def wrapper(*args, **kwargs):
            warnings = __import__('warnings')
            warnings.warn(message, warnings.DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not isinstance(s, str):
        raise TypeError("Input must be a string")
    s = s.strip()
    if not s:
        return ()
    import re
    parts = re.findall(r'\d+', s)
    return tuple(int(p) for p in parts)

def hashkey(*args, **kwargs):
    """Generate a hashable key from function arguments."""
    return (args, tuple(sorted(kwargs.items())))

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.
    """
    if cache is None:
        raise ValueError("cache must not be None")
    if not callable(key):
        raise TypeError("key must be callable")
    if not (hasattr(cache, "__contains__") and hasattr(cache, "__getitem__") and hasattr(cache, "__setitem__")):
        raise TypeError("cache must support __contains__, __getitem__, and __setitem__")
    if lock is not None and not (hasattr(lock, "__enter__") and hasattr(lock, "__exit__")):
        raise TypeError("lock must be a context manager if provided")

    def decorator(func):
        def wrapper(*args, **kwargs):
            try:
                k = key(*args, **kwargs)
            except Exception as e:
                raise RuntimeError(f"Key function raised an exception: {e}") from e
            if lock:
                try:
                    with lock:
                        if k in cache:
                            return cache[k]
                except Exception as e:
                    raise RuntimeError(f"Lock acquisition failed during cache lookup: {e}") from e
            else:
                if k in cache:
                    return cache[k]
            result = func(*args, **kwargs)
            if lock:
                try:
                    with lock:
                        cache[k] = result
                except Exception as e:
                    raise RuntimeError(f"Lock acquisition failed during cache set: {e}") from e
            else:
                cache[k] = result
            return result
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        return wrapper
    return decorator

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    # Validate parameters
    if not isinstance(maxsize, int) or maxsize < 0:
        raise TypeError("maxsize must be a non-negative integer")
    if not isinstance(ttl, (int, float)) or ttl < 0:
        raise TypeError("ttl must be a non-negative number")
    if not callable(timer):
        raise TypeError("timer must be a callable returning a monotonic time")
    if not isinstance(typed, bool):
        raise TypeError("typed must be a boolean")

    def decorator(func):
        if maxsize == 0:
            # No caching; return the original function
            return func

        cache = OrderedDict()

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            # Build cache key
            if typed:
                key = args + tuple(sorted(kwargs.items())) + \
                      tuple(type(v) for v in args) + \
                      tuple(type(v) for v in kwargs.values())
            else:
                key = args + tuple(sorted(kwargs.items()))

            now = timer()
            # Check cache
            if key in cache:
                value, expire = cache[key]
                if now < expire:
                    # Move to end to mark as recently used
                    cache.move_to_end(key)
                    return value
                else:
                    # Expired entry
                    del cache[key]

            # Compute new value
            try:
                result = func(*args, **kwargs)
            except Exception:
                # Do not cache exceptions
                raise

            expire_time = now + ttl
            cache[key] = (result, expire_time)
            cache.move_to_end(key)

            # Enforce maxsize
            if len(cache) > maxsize:
                cache.popitem(last=False)

            return result

        # Expose cache for introspection
        wrapper.cache = cache
        return wrapper

    return decorator

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    # Attempt to use OrderedDict's popitem with last=False if available
    try:
        return super().popitem(last=False)
    except (TypeError, AttributeError):
        # Fallback for dict-like objects
        if hasattr(self, "keys") and hasattr(self, "pop"):
            try:
                first_key = next(iter(self))
            except StopIteration:
                raise KeyError("popitem(): dictionary is empty")
            value = self.pop(first_key)
            return (first_key, value)
        # If the object is not dict-like, raise a clear error
        raise TypeError("popitem() not supported for this object")

def setdefault(self, key, default=None):
    """
    D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D
    """
    try:
        if key in self:
            return self[key]
        else:
            self[key] = default
            return default
    except TypeError as e:
        # Likely the key is unhashable
        raise TypeError(f"Unhashable key: {key}") from e
    except Exception as e:
        # General error handling for setting the default
        raise RuntimeError(f"Error setting default for key {key}") from e

def get(self, key, default=None):
    """
    Return the value for key if key is in the dictionary, else default.
    """
    try:
        return self[key]
    except KeyError:
        return default
    except TypeError as e:
        # This can happen if the key is unhashable or if self is not subscriptable
        raise TypeError(f"Invalid key or object for get: {e}") from e
    except Exception as e:
        # Re-raise any other unexpected exceptions
        raise e

def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.
    """
    if cache is None:
        raise TypeError("cache must be provided")
    if not callable(key):
        raise TypeError("key must be callable")
    def decorator(func):
        def wrapper(*args, **kwargs):
            # Compute the cache key
            try:
                k = key(*args, **kwargs)
            except Exception:
                # Fallback key if key function fails
                k = (args, tuple(sorted(kwargs.items())))
            # Helper to get from cache
            def get_from_cache():
                try:
                    return cache[k]
                except Exception:
                    try:
                        return cache.get(k)
                    except Exception:
                        raise KeyError
            # Helper to set cache
            def set_in_cache(value):
                try:
                    cache[k] = value
                except Exception:
                    try:
                        cache.set(k, value)
                    except Exception:
                        pass
            # Acquire lock if provided
            if lock is not None:
                # Try context manager protocol
                try:
                    with lock:
                        try:
                            return get_from_cache()
                        except KeyError:
                            result = func(*args, **kwargs)
                            set_in_cache(result)
                            return result
                except Exception:
                    # Fallback to explicit acquire/release
                    try:
                        lock.acquire()
                        try:
                            try:
                                return get_from_cache()
                            except KeyError:
                                result = func(*args, **kwargs)
                                set_in_cache(result)
                                return result
                        finally:
                            lock.release()
                    except Exception:
                        # If lock cannot be used, proceed without it
                        pass
            # No lock or lock failed
            try:
                return get_from_cache()
            except KeyError:
                result = func(*args, **kwargs)
                set_in_cache(result)
                return result
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        return wrapper
    return decorator

@classmethod
def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception into a readable string with a limited stack trace depth
    and truncated file paths.

    :param e: Any exception instance.
    :type e: Exception
    :param max_level: Maximum number of stack frames to include (default 30)
    :type max_level: int
    :param max_path_level: Maximum number of path components to display (default 5)
    :type max_path_level: int
    :return: A formatted string representation of the exception.
    :rtype: str
    """
    import traceback
    import os

    # Ensure we have a BaseException instance
    if not isinstance(e, BaseException):
        return str(e)

    # Helper to truncate file paths
    def truncate_path(path, max_parts):
        parts = path.split(os.sep)
        if len(parts) > max_parts:
            return os.sep.join(['...'] + parts[-max_parts:])
        return path

    # Build the main exception message
    lines = [f"{type(e).__name__}: {e}"]

    # Extract traceback frames
    tb = e.__traceback__
    if tb is not None:
        stack = traceback.extract_tb(tb)
        # Limit to the last `max_level` frames
        for frame in stack[-max_level:]:
            file_path = truncate_path(frame.filename, max_path_level)
            lines.append(f'  File "{file_path}", line {frame.lineno}, in {frame.name}')
            if frame.line:
                lines.append(f'    {frame.line.strip()}')

    # Handle chained exceptions (__cause__ and __context__)
    def _append_chain(exc, prefix):
        if exc is None:
            return
        lines.append(prefix)
        lines.append(cls.extostr(exc, max_level, max_path_level))

    if e.__cause__ is not None:
        _append_chain(e.__cause__, "Caused by:")
    elif e.__context__ is not None and not e.__suppress_context__:
        _append_chain(e.__context__, "During handling of the above exception, another exception occurred:")

    return "\n".join(lines)

@staticmethod
def file_to_textbuffer(file_name, encoding):
    """
    Load a file toward a text buffer (UTF-8), using the specify encoding while reading.
    CAUTION : This will read the whole file IN MEMORY.
    :param file_name: File name.
    :type file_name: str
    :param encoding: Encoding to use.
    :type encoding: str
    :return: A text buffer or None in case of error.
    :rtype str
    """
    if not isinstance(file_name, str) or not isinstance(encoding, str):
        return None
    try:
        with open(file_name, 'r', encoding=encoding) as f:
            return f.read()
    except Exception:
        return None

@staticmethod
def is_file_exist(file_name):
    """
    Check if file name exist.
    :param file_name: File name.
    :type file_name: str
    :return: Return true (exist), false (do not exist, or invalid file name)
    :rtype bool
    """
    # Validate input
    if not isinstance(file_name, str) or not file_name:
        return False
    try:
        import os
        return os.path.isfile(file_name)
    except Exception:
        return False

def _getTargetClass(self):
    """
    Define this to return the implementation in use,
    without the 'Py' or 'Fallback' suffix.
    """
    try:
        # Attempt to locate the implementation attribute
        impl = getattr(self, 'implementation', None)
        if impl is None:
            impl = getattr(self, 'impl', None)
        # Fallback to the class of the instance itself
        if impl is None:
            impl = type(self)
        # Determine the class name
        if isinstance(impl, type):
            class_name = impl.__name__
        else:
            class_name = type(impl).__name__
        # Strip known suffixes
        for suffix in ('Py', 'Fallback'):
            if class_name.endswith(suffix):
                class_name = class_name[:-len(suffix)]
                break
        return class_name
    except Exception as exc:
        raise RuntimeError(f"Unable to determine target class: {exc}") from exc

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    # Validate that classes is iterable
    if not hasattr(classes, "__iter__"):
        raise TypeError("classes must be an iterable of classes")
    # Convert to list for multiple passes
    class_list = list(classes)
    # Validate each element is a class
    for c in class_list:
        if not isinstance(c, type):
            raise TypeError(f"Element {c!r} is not a class")
    # Determine which classes are superclasses of any other class in the list
    redundant = set()
    n = len(class_list)
    for i in range(n):
        ci = class_list[i]
        for j in range(n):
            if i == j:
                continue
            cj = class_list[j]
            if issubclass(cj, ci):
                redundant.add(ci)
                break
    # Build the minimal ordered list, preserving first occurrence and removing duplicates
    seen = set()
    result = []
    for c in class_list:
        if c in redundant:
            continue
        if c in seen:
            continue
        result.append(c)
        seen.add(c)
    return result

def _should_attempt_c_optimizations():
    """
    Return a true value if we should attempt to use the C optimizations.

    This takes into account whether we're on PyPy and the value of the
    ``PURE_PYTHON`` environment variable, as defined in `_use_c_impl`.
    """
    try:
        import sys
        import os
    except Exception:
        # If we cannot import required modules, be conservative and do not attempt C optimizations
        return False

    # Do not attempt C optimizations on PyPy
    try:
        if getattr(sys, "implementation", None) and getattr(sys.implementation, "name", None) == "pypy":
            return False
    except Exception:
        # If we cannot determine the implementation, fall through to other checks
        pass

    # Respect the PURE_PYTHON environment variable
    try:
        pure_python = os.getenv("PURE_PYTHON")
        if pure_python is not None:
            pure_python = pure_python.strip().lower()
            if pure_python in ("1", "true", "yes", "on"):
                return False
    except Exception:
        # If we cannot read the environment variable, ignore it
        pass

    # Default to attempting C optimizations
    return True

def _c_optimizations_ignored():
    """
    The opposite of `_c_optimizations_required`.
    """
    try:
        required = _c_optimizations_required()
        return not bool(required)
    except Exception:
        # If we cannot determine if optimizations are required, assume they are ignored
        return True

def _c_optimizations_required():
    """
    Return a true value if the C optimizations are required.

    This uses the ``PURE_PYTHON`` variable as documented in `_use_c_impl`.
    """
    try:
        # If PURE_PYTHON is truthy, C optimizations are not required.
        return not bool(PURE_PYTHON)
    except Exception:
        # If PURE_PYTHON is not defined or any other error occurs,
        # assume C optimizations are not required.
        return False

def reset(self):
        """Reset the histogram.

        Current context is reset to an empty dict.
        Bins are reinitialized with the *initial_value*
        or with *make_bins()* (depending on the initialization).
        """
        # Reset the context
        self.context = {}

        # Reinitialize bins
        try:
            if getattr(self, "initial_value", None) is not None:
                # If an initial value is provided, fill all bins with it.
                # Use the existing number of bins if available, otherwise
                # fall back to the length of the current bins list.
                num_bins = getattr(self, "num_bins", None)
                if num_bins is None:
                    # Try to infer from current bins
                    current_bins = getattr(self, "bins", None)
                    if current_bins is None:
                        raise ValueError("Cannot determine number of bins for reset.")
                    num_bins = len(current_bins)
                self.bins = [self.initial_value] * num_bins
            else:
                # No initial value: use the factory method to create bins.
                if not hasattr(self, "make_bins") or not callable(self.make_bins):
                    raise AttributeError("Histogram has no callable make_bins method.")
                self.bins = self.make_bins()
        except Exception as exc:
            # Wrap any exception to provide a clear error message
            raise RuntimeError(f"Failed to reset histogram bins: {exc}") from exc

def to_csv(self, separator=",", header=None):
    """
    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.
    """
    # Validate separator
    if not isinstance(separator, str):
        raise TypeError("separator must be a string")
    # Validate header
    if header is not None and not isinstance(header, str):
        raise TypeError("header must be a string or None")

    lines = []

    # Add header if provided
    if header is not None:
        lines.append(header)

    # Ensure points iterable
    points = getattr(self, "points", None)
    if points is None:
        return "\n".join(lines)

    for point in points:
        try:
            coord, value = point
        except Exception as exc:
            raise ValueError(f"Point {point!r} is not a (coordinate, value) pair") from exc

        # Convert coordinate
        if isinstance(coord, (list, tuple)):
            coord_str = separator.join(str(c) for c in coord)
        else:
            coord_str = str(coord)

        # Convert value
        if isinstance(value, (list, tuple)):
            value_str = separator.join(str(v) for v in value)
        else:
            value_str = str(value)

        line = separator.join([coord_str, value_str])
        lines.append(line)

    return "\n".join(lines)

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    if not isinstance(coord_name, str):
        raise TypeError("coord_name must be a string")
    if not hasattr(self, "_err_indices"):
        raise AttributeError("Missing _err_indices attribute")
    err_indices = self._err_indices
    if isinstance(err_indices, dict):
        try:
            return err_indices[coord_name]
        except KeyError:
            raise KeyError(f"Coordinate name '{coord_name}' not found in error indices mapping")
    elif isinstance(err_indices, (list, tuple)):
        if not hasattr(self, "_coord_names"):
            raise AttributeError("Missing _coord_names attribute for list-based error indices")
        try:
            idx = self._coord_names.index(coord_name)
        except ValueError:
            raise KeyError(f"Coordinate name '{coord_name}' not found in coordinate names")
        return err_indices[idx]
    else:
        raise TypeError("Unsupported type for _err_indices attribute")

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Basic type checks
    if bins is None or edges is None:
        raise TypeError("bins and edges must not be None")
    if isinstance(bins, (str, bytes)) or isinstance(edges, (str, bytes)):
        raise TypeError("bins and edges must be iterable of numbers, not strings")
    try:
        iter(bins)
    except TypeError:
        raise TypeError("bins must be an iterable of numbers")
    try:
        iter(edges)
    except TypeError:
        raise TypeError("edges must be an iterable of numbers")

    # Convert to lists to allow multiple passes
    bins_list = list(bins)
    edges_list = list(edges)

    # Empty or insufficient edges: integral is zero
    if len(edges_list) < 2:
        return 0.0
    # Number of bins must match number of edges minus one
    if len(bins_list) != len(edges_list) - 1:
        raise ValueError("Number of bins must be one less than number of edges")

    # Validate edges: numeric, sorted ascending, no NaN or infinite
    prev_edge = None
    for idx, e in enumerate(edges_list):
        try:
            e_val = float(e)
        except Exception:
            raise TypeError(f"Edge at index {idx} is not a numeric value")
        if e_val != e_val:  # NaN check
            raise ValueError(f"Edge at index {idx} is NaN")
        if e_val == float('inf') or e_val == float('-inf'):
            raise ValueError(f"Edge at index {idx} is infinite")
        if prev_edge is not None and e_val < prev_edge:
            raise ValueError("Edges must be sorted in ascending order")
        prev_edge = e_val

    # Compute widths and validate
    widths = []
    for i in range(len(edges_list) - 1):
        w = edges_list[i + 1] - edges_list[i]
        try:
            w_val = float(w)
        except Exception:
            raise TypeError(f"Width between edges {i} and {i+1} is not numeric")
        if w_val != w_val:  # NaN
            raise ValueError(f"Width between edges {i} and {i+1} is NaN")
        if w_val == float('inf') or w_val == float('-inf'):
            raise ValueError(f"Width between edges {i} and {i+1} is infinite")
        if w_val < 0:
            raise ValueError(f"Negative width between edges {i} and {i+1}")
        widths.append(w_val)

    # Validate bins and compute integral
    integral_value = 0.0
    for idx, (b, w) in enumerate(zip(bins_list, widths)):
        try:
            b_val = float(b)
        except Exception:
            raise TypeError(f"Bin at index {idx} is not numeric")
        if b_val != b_val:  # NaN
            raise ValueError(f"Bin at index {idx} is NaN")
        if b_val == float('inf') or b_val == float('-inf'):
            raise ValueError(f"Bin at index {idx} is infinite")
        integral_value += b_val * w

    return float(integral_value)

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    try:
        # Attempt to reference the expected classes if they exist
        try:
            FillRequest
        except NameError:
            FillRequest = None
        try:
            Source
        except NameError:
            Source = None

        # If seq itself is a FillRequest instance
        if FillRequest is not None and isinstance(seq, FillRequest):
            return True

        # If seq is a Source instance, reject it
        if Source is not None and isinstance(seq, Source):
            return False

        # Try to iterate over seq; if not iterable, return False
        try:
            iterator = iter(seq)
        except TypeError:
            return False

        # Check each element for a FillRequest instance
        for item in iterator:
            if FillRequest is not None and isinstance(item, FillRequest):
                return True

        return False
    except Exception:
        # Any unexpected error results in a False verdict
        return False

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
    try:
        return callable(getattr(obj, 'fill')) and callable(getattr(obj, 'request'))
    except Exception:
        return False

def is_run_el(obj):
    """Object contains executable method 'run'."""
    try:
        return callable(getattr(obj, 'run'))
    except Exception:
        return False

def is_fill_compute_el(obj):
    """Object contains executable methods 'fill' and 'compute'."""
    try:
        return callable(getattr(obj, 'fill')) and callable(getattr(obj, 'compute'))
    except Exception:
        return False

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    # Validate inputs
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("d1 and d2 must be dictionaries")
    if not isinstance(level, int):
        raise TypeError("level must be an integer")
    if level < -1:
        raise ValueError("level must be -1 or a non-negative integer")

    def _diff(sub_d1, sub_d2, cur_level):
        result = {}
        for key, val1 in sub_d1.items():
            if key not in sub_d2:
                # Key only in d1
                result[key] = val1
            else:
                val2 = sub_d2[key]
                # Both values are dictionaries
                if isinstance(val1, dict) and isinstance(val2, dict):
                    if cur_level == 0:
                        # No further recursion; include if values differ
                        if val1 != val2:
                            result[key] = val1
                    else:
                        # Recurse
                        next_level = cur_level - 1 if cur_level > 0 else -1
                        sub_diff = _diff(val1, val2, next_level)
                        if sub_diff:
                            result[key] = sub_diff
                else:
                    # Non-dict values or mismatched types
                    if val1 != val2:
                        result[key] = val1
        return result

    return _diff(d1, d2, level)

def fill(self, coord, weight=1):
    """
    Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Validate coordinate
    try:
        # Ensure coord is iterable
        if not hasattr(coord, "__iter__"):
            raise TypeError("coord must be an iterable of coordinates")
        coord = list(coord)
        if len(coord) != len(self.edges):
            raise ValueError("coord dimension does not match histogram dimensions")
    except Exception as exc:
        raise ValueError(f"Invalid coordinate: {exc}") from exc

    # Find bin indices for each dimension
    indices = []
    for c, edge in zip(coord, self.edges):
        # Use numpy's searchsorted if available; fallback to manual search
        try:
            # np.searchsorted returns insertion index; subtract 1 to get bin index
            idx = np.searchsorted(edge, c, side="right") - 1
        except NameError:
            # Manual binary search
            lo, hi = 0, len(edge) - 1
            idx = -1
            while lo <= hi:
                mid = (lo + hi) // 2
                if edge[mid] <= c:
                    idx = mid
                    lo = mid + 1
                else:
                    hi = mid - 1
        # Check if coordinate is outside the histogram range
        if idx < 0 or idx >= len(edge) - 1:
            return  # ignore out-of-range coordinates
        indices.append(idx)

    # Increment the histogram bin by the weight
    try:
        self.data[tuple(indices)] += weight
    except Exception as exc:
        raise ValueError(f"Failed to increment histogram bin: {exc}") from exc

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    errors = []

    # Assume LABEL_KEY_REGEX and LABEL_VALUE_REGEX are defined globally
    # and re is available globally.
    for key, value in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            errors.append({str(key): 'expected string or bytes-like object'})
        else:
            # Validate key regex
            try:
                if not re.match(LABEL_KEY_REGEX, key):
                    errors.append({key: f"Label key '{key}' does not match the regex [...]"})
            except Exception:
                # If regex matching fails due to invalid regex, skip
                pass

        # Validate value type
        if not isinstance(value, (str, bytes)):
            errors.append({str(value): 'expected string or bytes-like object'})
        else:
            # Validate value regex
            try:
                if not re.match(LABEL_VALUE_REGEX, value):
                    errors.append({value: f"Label value '{value}' does not match the regex [...]"})
            except Exception:
                pass

    if errors:
        raise ValidationError(errors)

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """
    Recursively update a partial ``last_applied_manifest`` list from a partial
    Kubernetes response according to the provided ``observer_schema``.

    The function walks through each element of ``observer_schema`` and ensures
    that the corresponding element in ``last_applied_manifest`` is populated
    with the value from ``response`` if it is missing. Nested dictionaries
    and lists are handled by delegating to the appropriate helper functions.

    Parameters
    ----------
    last_applied_manifest : list
        The list that will be updated in place.
    observer_schema : list
        A list describing the expected structure of the manifest. Each item
        may be a dict with a ``type`` key ('dict', 'list', or a value type)
        and an optional ``schema`` key for nested structures.
    response : list
        The partial response from the Kubernetes API that contains the
        values to be merged into ``last_applied_manifest``.

    Returns
    -------
    None
        The function modifies ``last_applied_manifest`` in place.
    """
    # Basic type checks
    if not isinstance(last_applied_manifest, list):
        raise TypeError("last_applied_manifest must be a list")
    if not isinstance(observer_schema, list):
        raise TypeError("observer_schema must be a list")
    if not isinstance(response, list):
        raise TypeError("response must be a list")

    # Ensure the manifest list is at least as long as the schema
    for i in range(len(observer_schema)):
        # Get the schema item and the corresponding response value if available
        schema_item = observer_schema[i]
        resp_val = response[i] if i < len(response) else None

        # Helper to ensure the list has an element at index i
        def ensure_index(lst, idx, default_factory):
            if idx >= len(lst):
                # Extend with defaults up to idx
                lst.extend([default_factory() for _ in range(idx - len(lst) + 1)])
            return lst[idx]

        # Process based on the type of the schema item
        if isinstance(schema_item, dict):
            schema_type = schema_item.get("type")
            if schema_type == "dict":
                # Ensure a dict exists at this position
                current = ensure_index(
                    last_applied_manifest, i, lambda: {}
                )
                if not isinstance(current, dict):
                    # Replace with a new dict if type mismatch
                    current = {}
                    last_applied_manifest[i] = current
                # Recursively update the nested dict
                sub_schema = schema_item.get("schema", [])
                sub_resp = resp_val if isinstance(resp_val, dict) else {}
                update_last_applied_manifest_dict_from_resp(
                    current, sub_schema, sub_resp
                )
            elif schema_type == "list":
                # Ensure a list exists at this position
                current = ensure_index(
                    last_applied_manifest, i, lambda: []
                )
                if not isinstance(current, list):
                    current = []
                    last_applied_manifest[i] = current
                # Recursively update each element of the list
                sub_schema = schema_item.get("schema", [])
                sub_resp = resp_val if isinstance(resp_val, list) else []
                # If sub_schema is a dict, each element is a dict; otherwise simple values
                for j, elem_resp in enumerate(sub_resp):
                    if j >= len(current):
                        # Append a new element based on the schema type
                        if isinstance(sub_schema, dict):
                            new_elem = {}
                        else:
                            new_elem = None
                        current.append(new_elem)
                    if isinstance(sub_schema, dict):
                        # Nested dict element
                        update_last_applied_manifest_dict_from_resp(
                            current[j], sub_schema, elem_resp
                        )
                    else:
                        # Simple value element
                        if current[j] is None:
                            current[j] = elem_resp
            else:
                # Treat as a simple value
                current = ensure_index(
                    last_applied_manifest, i, lambda: None
                )
                if current is None:
                    last_applied_manifest[i] = resp_val
        else:
            # Schema item is not a dict; treat as a simple value
            current = ensure_index(
                last_applied_manifest, i, lambda: None
            )
            if current is None:
                last_applied_manifest[i] = resp_val

    # Trim any excess elements that are not described by the schema
    if len(last_applied_manifest) > len(observer_schema):
        del last_applied_manifest[len(observer_schema) :]
    return None

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response
        TypeError: If any of the arguments are of incorrect type or if the
            structure of the response does not match the observer schema.

    This function goes through all observed fields, and initializes their value in
    ``last_applied_manifest`` if they are not yet present.
    """
    # Basic type checks
    if not isinstance(last_applied_manifest, dict):
        raise TypeError("last_applied_manifest must be a dict")
    if not isinstance(observer_schema, dict):
        raise TypeError("observer_schema must be a dict")
    if not isinstance(response, dict):
        raise TypeError("response must be a dict")

    for key, sub_schema in observer_schema.items():
        if key not in response:
            raise KeyError(f"Observed field '{key}' not present in response")

        resp_value = response[key]

        # Handle nested dictionary
        if isinstance(sub_schema, dict):
            if not isinstance(resp_value, dict):
                raise TypeError(
                    f"Expected dict for field '{key}' in response, got {type(resp_value).__name__}"
                )
            # Ensure the target is a dict
            if key not in last_applied_manifest or not isinstance(
                last_applied_manifest[key], dict
            ):
                last_applied_manifest[key] = {}
            # Recurse into nested dict
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[key], sub_schema, resp_value
            )
        # Handle list
        elif isinstance(sub_schema, list):
            if not isinstance(resp_value, list):
                raise TypeError(
                    f"Expected list for field '{key}' in response, got {type(resp_value).__name__}"
                )
            # Ensure the target is a list
            if key not in last_applied_manifest or not isinstance(
                last_applied_manifest[key], list
            ):
                last_applied_manifest[key] = []
            # Delegate to list handler
            update_last_applied_manifest_list_from_resp(
                last_applied_manifest[key], sub_schema, resp_value
            )
        # Handle scalar or other types
        else:
            if key not in last_applied_manifest:
                last_applied_manifest[key] = resp_value
    # No explicit return needed; the dict is modified in place.

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema

    Returns:
        dict: A mapping from resource kind to its default observer schema.
    """
    if app is None:
        raise ValueError("app must not be None")

    spec = getattr(app, "spec", None)
    if spec is None:
        raise ValueError("app.spec is missing")

    # Get the list of resources; treat missing or non-list values as empty
    manifest = getattr(spec, "manifest", [])
    if manifest is None or not isinstance(manifest, list):
        manifest = []

    # Existing custom observer schemas
    existing = getattr(spec, "observer_schema", {})
    if existing is None or not isinstance(existing, dict):
        existing = {}

    # Default schema to use for resources without a custom schema
    default_schema = {
        "metadata": {
            "name": {"type": "string"},
            "namespace": {"type": "string"}
        },
        "status": {"type": "object"}
    }

    result = {}
    for resource in manifest:
        if not isinstance(resource, dict):
            continue
        kind = resource.get("kind")
        if not isinstance(kind, str) or not kind:
            continue
        if kind in existing:
            continue
        if kind in result:
            continue
        # Use a shallow copy to avoid accidental mutation of the default schema
        result[kind] = {
            "metadata": {
                "name": {"type": "string"},
                "namespace": {"type": "string"}
            },
            "status": {"type": "object"}
        }

    return result

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        from pathlib import Path
    except Exception:
        return False

    try:
        p = Path(path)
    except Exception:
        return False

    if not p.is_dir():
        return False

    # Check for .ocfl_version file
    version_file = p / ".ocfl_version"
    if not version_file.is_file():
        return False
    try:
        version = version_file.read_text().strip()
    except Exception:
        return False
    if not version:
        return False

    # Check for .ocfl_root file
    root_file = p / ".ocfl_root"
    if not root_file.is_file():
        return False
    try:
        root_dir_name = root_file.read_text().strip()
    except Exception:
        return False
    if not root_dir_name:
        return False

    # Verify that the root directory exists
    root_dir = p / root_dir_name
    if not root_dir.is_dir():
        return False

    # Optional: ensure the root directory contains at least one object directory
    # (an object directory typically contains a .ocfl_object file)
    try:
        has_object = any(
            (d.is_dir() and (d / ".ocfl_object").is_file())
            for d in root_dir.iterdir()
        )
    except Exception:
        return False
    if not has_object:
        return False

    return True

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    # Ensure prefix is a string; treat None as empty string
    try:
        prefix_str = str(prefix) if prefix is not None else ''
    except Exception:
        prefix_str = ''
    # Retrieve status from the instance; fall back to 'unknown' if not present
    status = getattr(self, 'status', None)
    if status is None:
        status_str = 'unknown'
    else:
        try:
            status_str = str(status)
        except Exception:
            status_str = 'unknown'
    return f"{prefix_str}{status_str}"

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    # Validate prefix
    if prefix is None:
        prefix = ''
    if not isinstance(prefix, str):
        raise TypeError(f"prefix must be a string, got {type(prefix).__name__}")

    # Retrieve the log from the instance; support common attribute names
    log = getattr(self, 'log', None)
    if log is None:
        log = getattr(self, 'validation_log', None)
    if log is None:
        # No log available; return empty string
        return ''

    # Ensure the log is iterable
    try:
        iterator = iter(log)
    except TypeError:
        raise TypeError(f"validation log must be an iterable, got {type(log).__name__}")

    # Build the string representation
    lines = []
    for entry in iterator:
        # Convert non-string entries to string
        if not isinstance(entry, str):
            try:
                entry_str = str(entry)
            except Exception:
                entry_str = '<unrepresentable entry>'
        else:
            entry_str = entry
        lines.append(f"{prefix}{entry_str}")

    return "\n".join(lines)

def validate(self, inventory, extract_spec_version=False):
    """
    Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    try:
        # Basic type check
        if not isinstance(inventory, dict):
            raise ValueError("Inventory must be a dictionary.")

        # Determine spec_version
        spec_version = getattr(self, "spec_version", None)
        if extract_spec_version:
            type_val = inventory.get("type")
            if isinstance(type_val, str):
                # Try to extract a version number from the type string
                import re
                match = re.search(r"v(\d+(?:\.\d+)*)", type_val)
                if match:
                    spec_version = match.group(1)

        # If we still don't have a spec_version, use the default
        if spec_version is None:
            raise ValueError("Specification version could not be determined.")

        # Validate spec_version against known supported versions
        supported_versions = {"1.0", "2.0", "3.0"}
        if spec_version not in supported_versions:
            raise ValueError(f"Unsupported spec_version: {spec_version}")

        # Basic inventory structure checks
        if "name" not in inventory or not isinstance(inventory["name"], str):
            raise ValueError("Inventory must contain a 'name' string field.")

        if "items" not in inventory or not isinstance(inventory["items"], list):
            raise ValueError("Inventory must contain an 'items' list field.")

        # Validate each item in the list
        for idx, item in enumerate(inventory["items"]):
            if not isinstance(item, dict):
                raise ValueError(f"Item at index {idx} must be a dictionary.")
            if "id" not in item or "value" not in item:
                raise ValueError(f"Item at index {idx} must contain 'id' and 'value' keys.")

        return True

    except Exception as exc:
        raise ValueError(f"Inventory validation failed: {exc}") from exc

def validate_as_prior_version(self, prior):
        """Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        # Ensure prior is not None
        if prior is None:
            raise ValueError("prior must not be None")

        # Ensure prior is an instance of the same class (or at least has the required attributes)
        if not isinstance(prior, type(self)):
            raise TypeError(f"prior must be an instance of {type(self).__name__}")

        # Required attributes that we expect to compare
        required_attrs = ("version", "inventory_id", "timestamp")
        for attr in required_attrs:
            if not hasattr(self, attr):
                raise AttributeError(f"Current object missing required attribute '{attr}'")
            if not hasattr(prior, attr):
                raise AttributeError(f"Prior object missing required attribute '{attr}'")

        # Compare inventory identifiers to ensure they refer to the same inventory
        if getattr(self, "inventory_id") != getattr(prior, "inventory_id"):
            return False

        # Compare timestamps to ensure prior is older
        try:
            self_ts = getattr(self, "timestamp")
            prior_ts = getattr(prior, "timestamp")
            if not isinstance(self_ts, (int, float)) or not isinstance(prior_ts, (int, float)):
                raise TypeError("timestamp attributes must be numeric")
            if prior_ts >= self_ts:
                return False
        except Exception as e:
            raise ValueError(f"Error comparing timestamps: {e}")

        # Compare version numbers to ensure prior is older
        try:
            self_ver = getattr(self, "version")
            prior_ver = getattr(prior, "version")
            if not isinstance(self_ver, (int, float)) or not isinstance(prior_ver, (int, float)):
                raise TypeError("version attributes must be numeric")
            if prior_ver >= self_ver:
                return False
        except Exception as e:
            raise ValueError(f"Error comparing versions: {e}")

        # If all checks pass, prior is a valid prior version
        return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Validate inventory
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dict mapping versions to logical path mappings")
    if not isinstance(version, (str, int)):
        raise TypeError("version must be a string or int")
    if version not in inventory:
        raise ValueError(f"Version {version!r} not found in inventory")

    # Determine the order of versions (preserve insertion order if possible)
    versions = list(inventory.keys())
    try:
        idx = versions.index(version)
    except ValueError:
        raise ValueError(f"Version {version!r} not found in inventory")

    # Get the mapping for the requested version
    version_map = inventory[version]
    if not isinstance(version_map, dict):
        raise TypeError(f"Inventory entry for version {version!r} must be a dict mapping logical paths to content files")

    result = {}
    for logical_path, content_file in version_map.items():
        if not isinstance(logical_path, str):
            raise TypeError(f"Logical path {logical_path!r} must be a string")
        if not isinstance(content_file, str):
            raise TypeError(f"Content file {content_file!r} for logical path {logical_path!r} must be a string")

        files_set = {content_file}

        # Include duplicates from later versions
        for later_version in versions[idx + 1 :]:
            later_map = inventory.get(later_version)
            if not isinstance(later_map, dict):
                continue
            later_file = later_map.get(logical_path)
            if isinstance(later_file, str):
                files_set.add(later_file)

        result[logical_path] = files_set

    return result

def validate_fixity(self, fixity, manifest_files):
    """
    Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Basic type checks
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary.")
    if not isinstance(manifest_files, (set, list, tuple)):
        raise ValueError("manifest_files must be a set, list, or tuple of file paths.")

    # Ensure required key exists
    if "files" not in fixity:
        raise ValueError("Fixity block missing required 'files' key.")
    files = fixity["files"]
    if not isinstance(files, list):
        raise ValueError("'files' entry in fixity block must be a list.")

    # Convert manifest_files to a set for efficient lookup
    manifest_set = set(manifest_files)

    # Validate each file entry
    for idx, entry in enumerate(files):
        if not isinstance(entry, dict):
            raise ValueError(f"File entry at index {idx} must be a dictionary.")
        if "path" not in entry:
            raise ValueError(f"File entry at index {idx} missing required 'path' key.")
        path = entry["path"]
        if not isinstance(path, str):
            raise ValueError(f"File path at index {idx} must be a string.")
        if path not in manifest_set:
            raise ValueError(f"File path '{path}' in fixity block not found in manifest files.")

    # All checks passed
    return True

def files_list(path):
    """
    Return the files in `path`
    """
    import os
    # Validate input type
    if not isinstance(path, (str, bytes, os.PathLike)):
        raise TypeError(f"path must be a string or path-like object, got {type(path).__name__}")
    # Resolve path to string
    try:
        path_str = os.fspath(path)
    except Exception as exc:
        raise TypeError(f"Invalid path object: {exc}") from exc
    # Check existence
    if not os.path.exists(path_str):
        raise FileNotFoundError(f"No such file or directory: '{path_str}'")
    # Check it's a directory
    if not os.path.isdir(path_str):
        raise NotADirectoryError(f"Not a directory: '{path_str}'")
    # List files
    try:
        entries = os.listdir(path_str)
    except PermissionError as exc:
        raise PermissionError(f"Permission denied accessing '{path_str}': {exc}") from exc
    except OSError as exc:
        raise OSError(f"Error listing directory '{path_str}': {exc}") from exc
    files = []
    for entry in entries:
        full_path = os.path.join(path_str, entry)
        if os.path.isfile(full_path):
            files.append(entry)
    return files

def _group_files_by_xml_filename(source, xmls, files):
    """
    Group files by their XML basename

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    source : str
        Path to the source directory (unused in this implementation).
    xmls : list
        List of XML filenames.
    files : list
        List of files in the folder or zipfile.

    Returns
    -------
    dict
        key: name of the XML files (basename without extension)
        value: list of files that share the same basename
    """
    # Validate inputs
    if not isinstance(xmls, list):
        raise TypeError("xmls must be a list")
    if not isinstance(files, list):
        raise TypeError("files must be a list")

    def _basename(path):
        # Extract the filename from a path without using os module
        return path.split('/')[-1].split('\\')[-1]

    def _stem(filename):
        # Return the filename without its extension
        return _basename(filename).rsplit('.', 1)[0]

    grouped = {}
    for xml in xmls:
        try:
            xml_stem = _stem(xml)
        except Exception:
            continue  # skip invalid xml names
        matched_files = []
        for f in files:
            try:
                if _stem(f) == xml_stem:
                    matched_files.append(f)
            except Exception:
                continue
        if matched_files:
            grouped[xml_stem] = matched_files
    return grouped

def fix_namespace_prefix_w(content):
    """
    Convert os textos cujo padrão é `w:st="` em `w-st="`
    """
    if content is None:
        raise ValueError("content cannot be None")
    if not isinstance(content, str):
        raise TypeError(f"content must be a string, got {type(content).__name__}")
    return content.replace('w:st="', 'w-st="')

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    # Validate inputs
    if node is None or not hasattr(node, "xpath"):
        raise TypeError("node must be an XML element supporting xpath()")
    if not isinstance(pubdate_xpaths, (list, tuple)):
        raise TypeError("pubdate_xpaths must be a list or tuple of XPath strings")
    if not pubdate_xpaths:
        return None

    for xpath_expr in pubdate_xpaths:
        if not isinstance(xpath_expr, str):
            continue  # skip non-string expressions
        try:
            result = node.xpath(xpath_expr)
        except Exception:
            # Skip invalid XPath expressions or evaluation errors
            continue
        if not result:
            continue
        # If the result is a list of elements or strings, return the first
        first = result[0]
        # If it's an lxml element, return its text content
        if hasattr(first, "text"):
            return first.text
        # If it's a string or other type, return it directly
        return first
    return None

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    # Validate parameters
    try:
        indent = int(indent)
        debug = bool(debug)
    except Exception:
        return '<Error: invalid indent or debug flag>'

    visited = set()

    def _pretty(obj, level):
        # Detect circular references
        if id(obj) in visited:
            return '... (circular reference)'
        visited.add(id(obj))

        # Primitive types
        if isinstance(obj, (str, int, float, bool, type(None))):
            return repr(obj)

        # Dictionaries
        if isinstance(obj, dict):
            if not obj:
                return '{}'
            items = []
            for k, v in obj.items():
                items.append(' ' * ((level + 1) * indent) + f'{repr(k)}: {_pretty(v, level + 1)}')
            return '{\n' + ',\n'.join(items) + '\n' + ' ' * (level * indent) + '}'

        # Sequences and sets
        if isinstance(obj, (list, tuple, set)):
            if not obj:
                if isinstance(obj, list):
                    return '[]'
                if isinstance(obj, tuple):
                    return '()'
                return '{}'
            items = []
            for v in obj:
                items.append(' ' * ((level + 1) * indent) + _pretty(v, level + 1))
            if isinstance(obj, list):
                opening, closing = '[', ']'
            elif isinstance(obj, tuple):
                opening, closing = '(', ')'
            else:
                opening, closing = '{', '}'
            return opening + '\n' + ',\n'.join(items) + '\n' + ' ' * (level * indent) + closing

        # Objects with __dict__
        if hasattr(obj, '__dict__'):
            return _pretty(obj.__dict__, level)

        # Fallback
        return repr(obj)

    try:
        result = _pretty(self, 0)
        if debug:
            result += f'\n# Debug: type={type(self).__name__}'
        return result
    except Exception as e:
        return f'<Error pretty printing: {e}>'

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    # Helper to recursively simplify an expression
    def _simplify(expr):
        try:
            # If the expression has subexpressions, simplify them first
            if hasattr(expr, "args") and expr.args:
                new_args = [_simplify(a) for a in expr.args]
                # Reconstruct the expression with simplified subexpressions
                expr = expr.func(*new_args)
            else:
                return expr

            # Determine the type of the expression
            func_name = getattr(expr.func, "__name__", None)

            # Absorption for And
            if func_name == "And":
                # Look for patterns A & (A | B) or A & (~A | B)
                for i, a in enumerate(expr.args):
                    if getattr(a, "func", None) and getattr(a.func, "__name__", None) == "Or":
                        for j, b in enumerate(expr.args):
                            if i == j:
                                continue
                            # Check for A & (A | B)
                            if b in a.args:
                                # Keep other arguments of the And
                                new_and_args = [b]
                                for k, c in enumerate(expr.args):
                                    if k not in (i, j):
                                        new_and_args.append(c)
                                return _simplify(expr.func(*new_and_args))
                            # Check for A & (~A | B)
                            for sub in a.args:
                                if getattr(sub, "func", None) and getattr(sub.func, "__name__", None) == "Not":
                                    if sub.args and sub.args[0] == b:
                                        # Build new And: A & B plus other arguments
                                        new_and_args = [b]
                                        for s in a.args:
                                            if s != sub:
                                                new_and_args.append(s)
                                        for k, c in enumerate(expr.args):
                                            if k not in (i, j):
                                                new_and_args.append(c)
                                        return _simplify(expr.func(*new_and_args))
                return expr

            # Absorption for Or
            if func_name == "Or":
                for i, a in enumerate(expr.args):
                    if getattr(a, "func", None) and getattr(a.func, "__name__", None) == "And":
                        for j, b in enumerate(expr.args):
                            if i == j:
                                continue
                            # Check for A | (A & B)
                            if b in a.args:
                                new_or_args = [b]
                                for k, c in enumerate(expr.args):
                                    if k not in (i, j):
                                        new_or_args.append(c)
                                return _simplify(expr.func(*new_or_args))
                            # Check for A | (~A & B)
                            for sub in a.args:
                                if getattr(sub, "func", None) and getattr(sub.func, "__name__", None) == "Not":
                                    if sub.args and sub.args[0] == b:
                                        new_or_args = [b]
                                        for s in a.args:
                                            if s != sub:
                                                new_or_args.append(s)
                                        for k, c in enumerate(expr.args):
                                            if k not in (i, j):
                                                new_or_args.append(c)
                                        return _simplify(expr.func(*new_or_args))
                return expr

            # For other expression types (including Not), just return as is
            return expr

        except Exception:
            # In case of any unexpected error, return the original expression
            return expr

    # Validate input
    if not isinstance(args, (list, tuple)):
        raise TypeError("args must be a sequence of expressions")

    # Simplify each expression in the list
    result = []
    for expr in args:
        try:
            result.append(_simplify(expr))
        except Exception:
            result.append(expr)
    return result

def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.
    """
    # Validate the hook argument
    if hook is None:
        raise ValueError("hook cannot be None")
    try:
        hash(hook)
    except Exception as exc:
        raise TypeError(f"hook must be hashable, got {type(hook).__name__}") from exc

    # Ensure the registry exists and is a dictionary
    if not hasattr(self, "_registry"):
        self._registry = {}
    if not isinstance(self._registry, dict):
        raise TypeError("registry must be a dict")

    # Create a list for this hook if it doesn't exist
    if hook not in self._registry:
        self._registry[hook] = []

    def decorator(func):
        if not callable(func):
            raise TypeError("listener must be callable")
        self._registry[hook].append(func)
        return func

    return decorator

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    if not callable(namefunc):
        raise TypeError("namefunc must be callable")
    import sys
    if sys.version_info[0] < 3:
        def wrapper(*args, **kwargs):
            result = namefunc(*args, **kwargs)
            if isinstance(result, unicode):
                try:
                    result = result.encode('utf-8')
                except UnicodeEncodeError as e:
                    raise ValueError("Failed to encode tzname result to bytes") from e
            return result
        return wrapper
    else:
        return namefunc

def get_versions():
    """Get version information or return default if unable to do so."""
    try:
        import os
        base_dir = os.path.dirname(__file__) if '__file__' in globals() else os.getcwd()
        version_file = os.path.join(base_dir, 'VERSION')
        with open(version_file, 'r', encoding='utf-8') as f:
            return f.read().strip()
    except Exception:
        return "0.0.0"

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Accept a pre-rendered string
    if isinstance(pieces, str):
        return pieces

    # Extract pieces
    try:
        if isinstance(pieces, dict):
            major = pieces.get('major')
            minor = pieces.get('minor')
            patch = pieces.get('patch')
            pre = pieces.get('pre_release')
            build = pieces.get('build')
        else:
            # Assume sequence: major, minor, patch, pre_release, build
            major = pieces[0] if len(pieces) > 0 else None
            minor = pieces[1] if len(pieces) > 1 else None
            patch = pieces[2] if len(pieces) > 2 else None
            pre = pieces[3] if len(pieces) > 3 else None
            build = pieces[4] if len(pieces) > 4 else None
    except Exception as exc:
        raise ValueError("Invalid pieces format") from exc

    # Helper to ensure numeric parts are present
    def _require(parts, names):
        for part, name in zip(parts, names):
            if part is None:
                raise ValueError(f"Missing {name} for {style} style")

    style = style.lower()
    if style == 'semver':
        _require((major, minor, patch), ('major', 'minor', 'patch'))
        version = f"{major}.{minor}.{patch}"
        if pre:
            version += f"-{pre}"
        if build:
            version += f"+{build}"
        return version

    if style == 'pep440':
        _require((major, minor), ('major', 'minor'))
        version = f"{major}.{minor}"
        if patch is not None:
            version += f".{patch}"
        if pre:
            # Treat pre as a dev release
            version += f".dev{pre}"
        if build:
            version += f"+{build}"
        return version

    if style == 'git':
        # Prefer pre-release (e.g., branch name or commit hash)
        if pre:
            return str(pre)
        if major is not None and minor is not None and patch is not None:
            return f"{major}.{minor}.{patch}"
        raise ValueError("Insufficient data for git style")

    if style == 'short':
        _require((major, minor), ('major', 'minor'))
        return f"{major}.{minor}"

    raise ValueError(f"Unsupported style: {style}")

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    if pieces is None:
        raise ValueError("pieces cannot be None")
    try:
        if '+' in pieces:
            return '.'
        else:
            return '+'
    except TypeError as e:
        raise TypeError("pieces must be an iterable of strings") from e

def register_vcs_handler(vcs, method):
    """
    Create decorator to mark a method as the handler of a VCS.
    """
    if not isinstance(vcs, str):
        raise TypeError("vcs must be a string")
    # Initialize registry if not present
    if not hasattr(register_vcs_handler, "_registry"):
        register_vcs_handler._registry = {}
    registry = register_vcs_handler._registry
    if callable(method):
        # Direct registration
        registry[vcs] = method
        return method
    else:
        # Return decorator
        def decorator(func):
            if not callable(func):
                raise TypeError("handler must be callable")
            registry[vcs] = func
            return func
        return decorator

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """
    Validate storage root hierarchy.

    Parameters
    ----------
    validate_objects : bool, optional
        If True, call each object's ``validate`` method (if it exists).
    check_digests : bool, optional
        If True, call each object's ``check_digest`` method (if it exists).
    show_warnings : bool, optional
        If True, print warnings when an object fails validation.

    Returns
    -------
    tuple
        (num_objects, good_objects) where
        * num_objects is the total number of objects examined,
        * good_objects is the number of objects that passed all requested checks.
    """
    # Validate input types
    for name, value in (('validate_objects', validate_objects),
                        ('check_digests', check_digests),
                        ('show_warnings', show_warnings)):
        if not isinstance(value, bool):
            raise TypeError(f"{name} must be a bool, got {type(value).__name__}")

    # Retrieve the collection of objects to validate
    objects = getattr(self, 'objects', None)
    if objects is None:
        objects = getattr(self, '_objects', None)
    if objects is None:
        objects = []

    # Ensure the collection is iterable
    try:
        iterator = iter(objects)
    except TypeError:
        raise TypeError("The 'objects' attribute must be an iterable")

    num_objects = 0
    good_objects = 0

    for obj in iterator:
        num_objects += 1
        is_valid = True

        # Validate the object itself
        if validate_objects:
            if hasattr(obj, 'validate'):
                try:
                    result = obj.validate()
                    if result is False:
                        is_valid = False
                except Exception as exc:
                    is_valid = False
                    if show_warnings:
                        print(f"Warning: object {obj!r} failed validate() with error: {exc}")
            else:
                # No validate method; assume valid
                pass

        # Check the object's digest
        if check_digests:
            if hasattr(obj, 'check_digest'):
                try:
                    result = obj.check_digest()
                    if result is False:
                        is_valid = False
                except Exception as exc:
                    is_valid = False
                    if show_warnings:
                        print(f"Warning: object {obj!r} failed check_digest() with error: {exc}")
            else:
                # No check_digest method; assume valid
                pass

        if is_valid:
            good_objects += 1

    return num_objects, good_objects

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    # Validate that the root path is defined
    root = getattr(self, "root_path", None)
    if not root:
        raise ValueError("The 'root_path' attribute must be set to a non-empty path.")
    root = str(root)

    # Ensure the root does not already exist
    if os.path.exists(root):
        raise FileExistsError(f"Root path '{root}' already exists.")

    try:
        # Create the root directory
        os.makedirs(root, exist_ok=False)

        # Create the .ocfl_root metadata file
        ocfl_root_path = os.path.join(root, ".ocfl_root")
        ocfl_root_data = {
            "ocfl_version": "1.0",
            "root_layout": "flat"
        }
        with open(ocfl_root_path, "w", encoding="utf-8") as f:
            json.dump(ocfl_root_data, f, indent=2)

        # Create the .ocfl_version file
        ocfl_version_path = os.path.join(root, ".ocfl_version")
        with open(ocfl_version_path, "w", encoding="utf-8") as f:
            f.write("1.0")

        # Create the .ocfl_objects directory
        objects_dir = os.path.join(root, ".ocfl_objects")
        os.makedirs(objects_dir, exist_ok=False)

    except Exception as exc:
        # Clean up partially created structure if an error occurs
        if os.path.isdir(root):
            try:
                # Remove any created files/directories
                for root_dir, dirs, files in os.walk(root, topdown=False):
                    for name in files:
                        os.remove(os.path.join(root_dir, name))
                    for name in dirs:
                        os.rmdir(os.path.join(root_dir, name))
                os.rmdir(root)
            except Exception:
                pass
        raise OSError(f"Failed to initialize OCFL root at '{root}': {exc}") from exc

    return root

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Basic input validation
    if not isinstance(version_dirs, list):
        raise TypeError("version_dirs must be a list")
    for idx, vdir in enumerate(version_dirs, start=1):
        if not isinstance(vdir, str):
            raise TypeError(f"Element {idx} of version_dirs is not a string")

    # Prepare storage for differences
    differences = {}

    # Load root inventory
    try:
        root_inv_path = os.path.join(self.root_dir, "inventory.json")
        with open(root_inv_path, "r", encoding="utf-8") as f:
            root_inventory = json.load(f)
    except NameError as e:
        raise RuntimeError("Required module 'os' or 'json' is not imported") from e
    except FileNotFoundError as e:
        raise FileNotFoundError(f"Root inventory file not found at {root_inv_path}") from e
    except json.JSONDecodeError as e:
        raise ValueError(f"Root inventory JSON is malformed: {e}") from e
    except Exception as e:
        raise RuntimeError(f"Unexpected error loading root inventory: {e}") from e

    if not isinstance(root_inventory, dict):
        raise ValueError("Root inventory must be a JSON object mapping file paths to digests")

    root_files = set(root_inventory.keys())

    # Validate each version inventory
    for vdir in version_dirs:
        inv_path = os.path.join(self.root_dir, vdir, "inventory.json")
        if not os.path.isfile(inv_path):
            raise FileNotFoundError(f"Inventory file missing for version '{vdir}' at {inv_path}")

        try:
            with open(inv_path, "r", encoding="utf-8") as f:
                inv = json.load(f)
        except json.JSONDecodeError as e:
            raise ValueError(f"Inventory JSON malformed for version '{vdir}': {e}") from e
        except Exception as e:
            raise RuntimeError(f"Error reading inventory for version '{vdir}': {e}") from e

        if not isinstance(inv, dict):
            raise ValueError(f"Inventory for version '{vdir}' must be a JSON object")

        inv_files = set(inv.keys())

        # Check that all root files are present in this version's inventory
        missing = root_files - inv_files
        if missing:
            raise ValueError(f"Inventory for version '{vdir}' is missing files: {sorted(missing)}")

        # Record any digest differences
        for file_path, digest in inv.items():
            root_digest = root_inventory.get(file_path)
            if root_digest is None:
                # File not in root inventory; skip comparison
                continue
            if digest != root_digest:
                differences.setdefault(file_path, []).append({
                    "version": vdir,
                    "inventory_digest": digest,
                    "root_digest": root_digest
                })

    # Store differences for later use
    self.differences = differences
    return differences

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os
    import re

    # Helper to return error string
    def err(msg):
        return f"Error: {msg}"

    # Check existence
    if not os.path.exists(path):
        return err("Path does not exist")

    # If it's a file, return 'file'
    if os.path.isfile(path):
        return 'file'

    # If it's a directory, look for Namaste file
    if os.path.isdir(path):
        try:
            entries = os.listdir(path)
        except OSError as e:
            return err(f"Cannot list directory: {e}")

        # Find file matching pattern "0=*"
        namaste_file = None
        for entry in entries:
            if re.match(r'^0=.*$', entry):
                namaste_file = entry
                break

        if not namaste_file:
            return err("No Namaste file found")

        namaste_path = os.path.join(path, namaste_file)
        try:
            with open(namaste_path, 'r', encoding='utf-8') as f:
                content = f.read()
        except OSError as e:
            return err(f"Cannot read Namaste file: {e}")

        # Determine type from content
        # OCFL Namaste file typically contains a line like "root" or "object"
        # We'll search for these keywords case-insensitively
        if re.search(r'\broot\b', content, re.IGNORECASE):
            return 'root'
        if re.search(r'\bobject\b', content, re.IGNORECASE):
            return 'object'

        return err("Namaste file does not indicate root or object")

    # If path is neither file nor directory
    return err("Path is neither file nor directory")

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    """
    # Validate that the parser has the expected attribute
    try:
        actions = parser._actions
    except Exception as exc:
        raise TypeError("Expected an argparse.ArgumentParser instance") from exc

    # Collect all option strings from each action
    flags = []
    for action in actions:
        # Some actions may not have option_strings (e.g., positional arguments)
        option_strings = getattr(action, "option_strings", [])
        if option_strings:
            flags.extend(option_strings)

    # Return a space-separated string of flags
    return " ".join(flags)

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    # Helper to determine if a node is a MappingNode
    def is_mapping(node):
        return hasattr(node, 'tag') and node.tag == 'tag:yaml.org,2002:map' and hasattr(node, 'value') and isinstance(node.value, list)

    # Merge two nodes: if both are mappings, merge recursively; otherwise, return new
    def merge_nodes(existing, new):
        if is_mapping(existing) and is_mapping(new):
            merge_mapping(existing, new)
            return existing
        else:
            return new

    # Merge mapping node 'existing' with mapping node 'new' in place
    def merge_mapping(existing, new):
        # Build a dict of existing keys to their index for quick lookup
        existing_index = {}
        for idx, (k_node, _) in enumerate(existing.value):
            existing_index[k_node.value] = idx
        # Iterate over new mapping entries
        for k_node, v_node in new.value:
            key = k_node.value
            if key in existing_index:
                # Replace the value at the existing index
                existing.value[existing_index[key]] = (k_node, merge_nodes(existing.value[existing_index[key]][1], v_node))
            else:
                # Append new key-value pair
                existing.value.append((k_node, v_node))

    # Main merging logic
    merged = {}
    for key_node, value_node in nodes:
        key = key_node.value
        if key in merged:
            merged[key] = merge_nodes(merged[key][1], value_node)
        else:
            merged[key] = (key_node, value_node)

    # Return list of tuples preserving the order of first appearance
    return [(k_node, v_node) for k_node, v_node in merged.values()]

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    # Validate that the input looks like an ArgumentParser
    if not hasattr(parser, '_actions'):
        raise TypeError('Expected an argparse.ArgumentParser instance')
    flags = []
    for action in parser._actions:
        # action.option_strings is a list of flag strings for this action
        flags.extend(action.option_strings)
    return ' '.join(flags)

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    # Basic input validation
    if not isinstance(unparsed_arguments, (list, tuple)):
        raise TypeError('unparsed_arguments must be a list or tuple of strings')
    if not isinstance(subparsers, dict):
        raise TypeError('subparsers must be a dict mapping names to ArgumentParser instances')
    for name, parser in subparsers.items():
        if not isinstance(name, str):
            raise TypeError('subparser names must be strings')
        if not hasattr(parser, 'parse_known_args'):
            raise TypeError('subparser values must have a parse_known_args method')

    parsed = {}
    try:
        from collections import Counter
    except Exception:
        # Fallback if collections is unavailable (unlikely)
        Counter = lambda: {}

    claimed_counter = Counter()

    for name, parser in subparsers.items():
        try:
            ns, remaining = parser.parse_known_args(unparsed_arguments)
        except SystemExit:
            # Parsing failed for this subparser; skip it
            continue
        # Determine which arguments were claimed by this subparser
        rem_copy = list(remaining)
        claimed = []
        for arg in unparsed_arguments:
            if arg in rem_copy:
                rem_copy.remove(arg)
            else:
                claimed.append(arg)
        # Update the global claimed counter
        for arg in claimed:
            claimed_counter[arg] += 1
        parsed[name] = ns

    # Compute arguments not claimed by any subparser
    remaining_args = []
    for arg in unparsed_arguments:
        if claimed_counter[arg] > 0:
            claimed_counter[arg] -= 1
        else:
            remaining_args.append(arg)

    return parsed, remaining_args

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    if not isinstance(url, str):
        raise TypeError("url must be a string")
    if url_args is None:
        url_args = {}
    if not isinstance(url_args, dict):
        raise TypeError("url_args must be a dict")
    result = []
    i = 0
    length = len(url)
    while i < length:
        if url[i] == '{':
            end = url.find('}', i + 1)
            if end == -1:
                raise ValueError("Unmatched '{' in URL")
            key = url[i + 1:end]
            if key == '':
                raise KeyError("Empty placeholder in URL")
            if key not in url_args:
                raise KeyError(f"Missing URL argument: {key}")
            value = url_args[key]
            result.append(str(value))
            i = end + 1
        else:
            result.append(url[i])
            i += 1
    return ''.join(result)

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    if not isinstance(val, str):
        return False
    s = val.strip().lower()
    return s in {"none", "null", "nil"}

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError(f"Expected a class, got {type(cls).__name__}")
    visited = set()

    def _rec(c):
        try:
            subs = c.__subclasses__()
        except Exception as e:
            raise RuntimeError(f"Error retrieving subclasses of {c.__name__}") from e
        for sub in subs:
            if sub not in visited:
                visited.add(sub)
                _rec(sub)

    _rec(cls)
    return visited

def string_to_int(string: str, alphabet: list) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    # Validate types
    if not isinstance(string, str):
        raise TypeError(f"string must be a str, got {type(string).__name__}")
    if not isinstance(alphabet, list):
        raise TypeError(f"alphabet must be a list, got {type(alphabet).__name__}")

    # Validate alphabet
    base = len(alphabet)
    if base <= 1:
        raise ValueError("alphabet must contain at least two distinct symbols for a valid base")
    seen = set()
    for idx, sym in enumerate(alphabet):
        if not isinstance(sym, str) or len(sym) != 1:
            raise TypeError(f"alphabet elements must be single-character strings, got {sym!r} at position {idx}")
        if sym in seen:
            raise ValueError(f"duplicate symbol {sym!r} found in alphabet")
        seen.add(sym)

    # Build mapping from symbol to digit value
    digit_map = {sym: i for i, sym in enumerate(alphabet)}

    # Validate string
    if not string:
        raise ValueError("input string must not be empty")

    result = 0
    for pos, ch in enumerate(string):
        if ch not in digit_map:
            raise ValueError(f"character {ch!r} at position {pos} not found in alphabet")
        result = result * base + digit_map[ch]

    return result

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    # Remove leading and trailing single or double quotes
    return re.sub(r"^['\"]|['\"]$", "", name)

def split(s, platform='this'):
    """
    Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    # Validate input
    if not isinstance(s, str):
        raise TypeError(f"Expected a string for 's', got {type(s).__name__}")
    # Determine platform
    if platform == 'this':
        try:
            import sys
            if sys.platform.startswith('win'):
                platform = 0
            else:
                platform = 1
        except Exception:
            platform = 1
    elif platform in (0, 1):
        pass
    else:
        raise ValueError(f"Invalid platform value: {platform!r}")
    # POSIX implementation using shlex
    if platform == 1:
        try:
            import shlex
            return shlex.split(s, posix=True)
        except Exception as exc:
            raise ValueError(f"POSIX split failed: {exc}") from exc
    # Windows implementation
    args = []
    current = []
    in_quotes = False
    backslashes = 0
    i = 0
    length = len(s)
    while i < length:
        c = s[i]
        if c == '\\':
            backslashes += 1
            i += 1
        elif c == '"':
            if backslashes % 2 == 0:
                # Even number of backslashes: half are escapes, toggle quote
                current.extend(['\\'] * (backslashes // 2))
                in_quotes = not in_quotes
            else:
                # Odd number: backslashes//2 escapes, quote is escaped
                current.extend(['\\'] * (backslashes // 2))
                current.append('"')
            backslashes = 0
            i += 1
        elif c.isspace() and not in_quotes:
            if backslashes:
                current.extend(['\\'] * backslashes)
                backslashes = 0
            if current:
                args.append(''.join(current))
                current = []
            # Skip consecutive whitespace
            i += 1
            while i < length and s[i].isspace():
                i += 1
        else:
            if backslashes:
                current.extend(['\\'] * backslashes)
                backslashes = 0
            current.append(c)
            i += 1
    # End of string
    if backslashes:
        current.extend(['\\'] * backslashes)
    if current:
        args.append(''.join(current))
    return args

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False
    try:
        # Check if host is an IPv4 address
        try:
            packed = socket.inet_aton(host)
            # IPv4 loopback is 127.0.0.0/8
            return packed[0] == 127
        except OSError:
            pass

        # Check if host is an IPv6 address
        try:
            packed = socket.inet_pton(socket.AF_INET6, host)
            # IPv6 loopback is ::1
            return host == '::1'
        except OSError:
            pass

        # Resolve hostname to addresses and check for loopback
        for res in socket.getaddrinfo(host, None):
            family, _, _, _, sockaddr = res
            if family == socket.AF_INET:
                ip = sockaddr[0]
                if ip.startswith('127.'):
                    return True
            elif family == socket.AF_INET6:
                ip = sockaddr[0]
                if ip == '::1':
                    return True
        return False
    except Exception:
        return False

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    # Validate input type
    if isinstance(matcher, str):
        # Split on the first colon to separate name and default
        parts = matcher.split(":", 1)
        name = parts[0].strip()
        default = parts[1] if len(parts) > 1 else None
    elif isinstance(matcher, tuple):
        if len(matcher) == 1:
            name, default = matcher[0], None
        elif len(matcher) == 2:
            name, default = matcher
        else:
            raise ValueError("Tuple matcher must contain 1 or 2 elements: (name,) or (name, default)")
    else:
        raise TypeError("Matcher must be a string or a tuple of (name,) or (name, default)")

    if not isinstance(name, str) or not name:
        raise ValueError("Environment variable name must be a non-empty string")

    # Retrieve the environment variable
    value = os.getenv(name)

    if value is None:
        if default is not None:
            return default
        else:
            raise KeyError(f"Environment variable '{name}' not set and no default provided.")
    return value

def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader
    """
    # Basic validation
    if graph is None:
        raise ValueError("graph must not be None")
    if prop is None:
        raise ValueError("prop must not be None")
    if not hasattr(graph, "triples"):
        raise TypeError("graph must support the triples() method (e.g., an rdflib Graph)")
    if roots is not None and not isinstance(roots, set):
        raise TypeError("roots must be a set of nodes or None")

    # Helper to collect parents and children for a set of nodes
    def _collect_parents_children(nodes: Set["Node"]) -> Tuple[Set["Node"], Set["Node"]]:
        parents = set()
        children = set()
        for node in nodes:
            try:
                for parent in graph.objects(node, prop):
                    parents.add(parent)
                    children.add(node)
            except Exception:
                # Skip nodes that cause errors
                continue
        return parents, children

    # If no specific roots are provided, find all roots in the graph
    if roots is None:
        all_parents = set()
        all_children = set()
        try:
            for _, _, parent in graph.triples((None, prop, None)):
                # child is the subject, parent is the object
                child = _
                all_parents.add(parent)
                all_children.add(child)
        except Exception:
            # In case graph.triples raises an error, fall back to objects()
            for child in graph.subjects(prop, None):
                for parent in graph.objects(child, prop):
                    all_parents.add(parent)
                    all_children.add(child)
        # Roots are parents that are not children
        return all_parents - all_children

    # If a set of roots is provided, find all ancestors of those roots
    # and then determine which of those ancestors have no parent.
    ancestors = set(roots)
    stack = list(roots)
    while stack:
        node = stack.pop()
        try:
            for parent in graph.objects(node, prop):
                if parent not in ancestors:
                    ancestors.add(parent)
                    stack.append(parent)
        except Exception:
            continue

    # Collect parents and children within the ancestor subgraph
    sub_parents, sub_children = _collect_parents_children(ancestors)

    # Roots are nodes that are either parents or ancestors but not children
    return (sub_parents | ancestors) - sub_children

def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    try:
        if dumper is None:
            s = yaml.safe_dump(obj, default_flow_style=False, allow_unicode=True)
        else:
            # Validate dumper
            if not isinstance(dumper, type) or not issubclass(dumper, yaml.Dumper):
                raise ValueError("dumper must be a subclass of yaml.Dumper")
            s = yaml.dump(obj, Dumper=dumper, default_flow_style=False, allow_unicode=True)
    except yaml.YAMLError as exc:
        raise ValueError(f"Error dumping object to YAML: {exc}") from exc
    except Exception as exc:
        raise ValueError(f"Unexpected error during YAML dump: {exc}") from exc

    # Ensure unicode in Python 2
    try:
        import sys
        if sys.version_info[0] < 3 and isinstance(s, bytes):
            try:
                s = s.decode('utf-8')
            except UnicodeDecodeError as exc:
                raise ValueError(f"Failed to decode YAML output: {exc}") from exc
    except Exception:
        # If sys import fails or any other issue, ignore
        pass

    return s

def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    try:
        sigma = 0.1
        center = 0.2
        return np.exp(-((x - center) ** 2) / (2 * sigma ** 2))
    except Exception as e:
        raise ValueError(f"Invalid input for gaussian: {e}") from e

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import json, os, logging, re
    if config_filenames is None:
        return {}, []
    try:
        filenames = list(config_filenames)
    except TypeError:
        raise TypeError("config_filenames must be an iterable of filenames")
    configs = {}
    errors = []
    env_pattern = re.compile(r'\$\{([^}]+)\}')
    def resolve_env_vars(value):
        if isinstance(value, str):
            def repl(match):
                return os.getenv(match.group(1), '')
            return env_pattern.sub(repl, value)
        elif isinstance(value, dict):
            return {k: resolve_env_vars(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [resolve_env_vars(v) for v in value]
        else:
            return value
    for fname in filenames:
        try:
            with open(fname, 'r', encoding='utf-8') as f:
                data = json.load(f)
            if not isinstance(data, dict):
                raise ValueError("Configuration must be a JSON object")
            if resolve_env:
                data = resolve_env_vars(data)
            if overrides:
                if not isinstance(overrides, dict):
                    raise ValueError("overrides must be a dict")
                data.update(overrides)
            configs[fname] = data
        except Exception as exc:
            msg = f"Error loading configuration '{fname}': {exc}"
            record = logging.LogRecord('config_loader', logging.ERROR, fname, 0, msg, None, None)
            errors.append(record)
    return configs, errors

def force_string(obj):
    """
    This function returns the bytes object corresponding to ``obj``
    in case it is a string using UTF-8.
    """
    if isinstance(obj, str):
        try:
            return obj.encode("utf-8")
        except Exception as exc:
            raise ValueError(f"Unable to encode string to UTF-8: {exc}") from exc
    return obj

@classmethod
def protocol_handlers(cls, protocol_version=None):
    """
    Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    # Retrieve the mapping of handlers from the class.  If the class
    # does not define it, raise an informative error.
    try:
        handlers = getattr(cls, "_protocol_handlers", {})
    except Exception as exc:
        raise AttributeError("Class does not define _protocol_handlers") from exc

    # Ensure we are working with a dictionary.  If the attribute is
    # something else (e.g., a list of tuples), attempt to convert it.
    if not isinstance(handlers, dict):
        try:
            handlers = dict(handlers)
        except Exception as exc:
            raise TypeError("Protocol handlers mapping must be a dict") from exc

    # If no specific protocol version is requested, return a copy of
    # all available handlers.
    if protocol_version is None:
        return dict(handlers)

    # Validate the supplied protocol_version.
    if not isinstance(protocol_version, tuple):
        raise TypeError("protocol_version must be a tuple")

    # Return a dictionary containing the handler for the requested
    # version if it exists, otherwise an empty dictionary.
    if protocol_version in handlers:
        return {protocol_version: handlers[protocol_version]}
    return {}

@classmethod
def from_raw_values(cls, values):
    """
    Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    :return: Bookmarks instance
    :raises TypeError: if values is not iterable or contains non-string items
    :raises ValueError: if any raw value cannot be parsed into a Bookmark
    """
    if values is None:
        raise TypeError("values must be an iterable of strings, got None")
    try:
        iterator = iter(values)
    except TypeError:
        raise TypeError(f"values must be an iterable of strings, got {type(values).__name__}")

    bookmarks = []
    for raw in iterator:
        if not isinstance(raw, str):
            raise TypeError(f"Each raw value must be a string, got {type(raw).__name__}")
        try:
            # Prefer a dedicated parsing method if available
            bookmark = Bookmark.from_raw_value(raw)
        except AttributeError:
            # Fallback to direct constructor
            bookmark = Bookmark(raw)
        except Exception as exc:
            raise ValueError(f"Failed to parse raw bookmark: {raw!r}") from exc
        bookmarks.append(bookmark)

    return cls(bookmarks)

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    # Attempt to locate the underlying mapping that stores the cache items.
    mapping = getattr(self, "_data", None)
    if mapping is None:
        mapping = getattr(self, "data", None)
    if mapping is None:
        raise AttributeError("Cache object has no mapping attribute")
    if not hasattr(mapping, "items"):
        raise TypeError("Cache mapping must support items()")
    try:
        # Prefer OrderedDict's popitem(last=False) if available.
        if hasattr(mapping, "popitem"):
            try:
                return mapping.popitem(last=False)
            except TypeError:
                # mapping.popitem does not accept 'last' (e.g., plain dict)
                pass
        # Fallback: manually remove the first item in insertion order.
        key, value = next(iter(mapping.items()))
        del mapping[key]
        return key, value
    except StopIteration:
        raise KeyError("popitem(): dictionary is empty")

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    try:
        # Attempt to use internal order tracking
        key = self._order.pop()
        value = self._data.pop(key)
        return key, value
    except (AttributeError, IndexError):
        # Fallback to dict popitem if available
        try:
            return super().popitem()
        except AttributeError:
            raise KeyError('popitem(): dictionary is empty')

def _create_converter(self) -> _converting._Converter:
    """
    Create the parameter style converter.

    Returns the parameter style converter (:class:`._converting._Converter`).
    """
    # Attempt to create a converter with no arguments first.
    try:
        return _converting._Converter()
    except TypeError:
        # The constructor may require a style argument. Try to fetch it from the instance.
        style = getattr(self, "parameter_style", None)
        if style is None:
            # If no style attribute is available, raise a clear error.
            raise RuntimeError(
                "Cannot create converter: no default constructor and no 'parameter_style' attribute found."
            )
        try:
            return _converting._Converter(style)
        except Exception as exc:
            # Wrap any exception to provide context.
            raise RuntimeError(
                f"Failed to create converter with style '{style}'."
            ) from exc
    except Exception as exc:
        # Catch any other unexpected errors during converter creation.
        raise RuntimeError("Unexpected error while creating converter.") from exc

def isoparse(self, dt_str):
    """
    Parse an ISO-8601 datetime string into a :class:`datetime.datetime`.

    See the module documentation for details on supported formats.
    """
    import re
    from datetime import datetime, date, timedelta
    try:
        from dateutil.tz import tzoffset, tzutc
    except Exception:
        # Fallback if dateutil is not available
        tzoffset = None
        tzutc = None

    if not isinstance(dt_str, str):
        raise TypeError("dt_str must be a string")

    s = dt_str.strip()
    if not s:
        raise ValueError("empty datetime string")

    # Split date and time+tz
    if 'T' in s:
        date_part, time_part = s.split('T', 1)
    else:
        # allow space separator
        parts = s.split()
        if len(parts) == 2:
            date_part, time_part = parts
        else:
            date_part, time_part = s, ''

    # Parse date part
    week_match = re.fullmatch(r'(?P<year>\d{4})-?W(?P<week>\d{2})(-?(?P<weekday>\d))?', date_part)
    if week_match:
        year = int(week_match.group('year'))
        week = int(week_match.group('week'))
        weekday = week_match.group('weekday')
        if weekday is None:
            weekday = 1  # default to Monday
        else:
            weekday = int(weekday)
            if not 1 <= weekday <= 7:
                raise ValueError(f"Invalid ISO week day: {weekday}")
        try:
            d = date.fromisocalendar(year, week, weekday)
        except Exception as e:
            raise ValueError(f"Invalid ISO week date: {e}") from None
    else:
        date_match = re.fullmatch(r'(?P<year>\d{4})(?:-?(?P<month>\d{2})(?:-?(?P<day>\d{2}))?)?', date_part)
        if not date_match:
            raise ValueError(f"Invalid date format: {date_part}")
        year = int(date_match.group('year'))
        month = date_match.group('month')
        day = date_match.group('day')
        month = int(month) if month else 1
        day = int(day) if day else 1
        try:
            d = date(year, month, day)
        except Exception as e:
            raise ValueError(f"Invalid date: {e}") from None

    # If time part is empty, default to midnight
    if not time_part:
        hour = minute = second = microsecond = 0
        tzinfo = None
    else:
        # Regex to capture time and optional timezone
        time_tz_pattern = re.compile(
            r'(?P<hour>\d{2})'
            r'(?::?(?P<minute>\d{2}))?'
            r'(?::?(?P<second>\d{2}))?'
            r'(?:[.,](?P<fraction>\d{1,6}))?'
            r'(?P<tz>Z|[+-]\d{2}(?::?\d{2})?)?$'
        )
        m = time_tz_pattern.fullmatch(time_part)
        if not m:
            raise ValueError(f"Invalid time format: {time_part}")

        hour = int(m.group('hour'))
        minute = int(m.group('minute')) if m.group('minute') else 0
        second = int(m.group('second')) if m.group('second') else 0
        fraction = m.group('fraction')
        microsecond = int(fraction.ljust(6, '0')) if fraction else 0

        # Validate ranges
        if hour > 24 or minute > 59 or second > 59 or microsecond > 999999:
            raise ValueError("Time component out of range")
        if hour == 24 and (minute != 0 or second != 0 or microsecond != 0):
            raise ValueError("24 hour must be followed by 00:00:00")

        tz_str = m.group('tz')
        if tz_str is None:
            tzinfo = None
        else:
            if tz_str == 'Z':
                tzinfo = tzutc() if tzutc else None
            else:
                sign = 1 if tz_str[0] == '+' else -1
                tz_body = tz_str[1:]
                if ':' in tz_body:
                    hh, mm = tz_body.split(':')
                else:
                    hh = tz_body[:2]
                    mm = tz_body[2:] if len(tz_body) > 2 else '00'
                try:
                    offset_hours = int(hh)
                    offset_minutes = int(mm)
                except Exception:
                    raise ValueError(f"Invalid timezone offset: {tz_str}")
                offset_seconds = sign * (offset_hours * 3600 + offset_minutes * 60)
                if tzoffset:
                    tzinfo = tzoffset(None, offset_seconds)
                else:
                    tzinfo = None

        # Handle 24:00:00 as midnight next day
        if hour == 24:
            hour = 0
            d += timedelta(days=1)

    # Construct datetime
    try:
        dt = datetime(d.year, d.month, d.day, hour, minute, second, microsecond, tzinfo=tzinfo)
    except Exception as e:
        raise ValueError(f"Failed to construct datetime: {e}") from None

    return dt

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    try:
        if request is None:
            return False

        # Check for public message via method or attribute
        if hasattr(request, "is_public_message"):
            try:
                if request.is_public_message():
                    return True
            except Exception:
                pass
        if getattr(request, "message_type", None) == "public":
            return True

        # Check for private message via method or attribute
        if hasattr(request, "is_private_message"):
            try:
                if request.is_private_message():
                    return True
            except Exception:
                pass
        if getattr(request, "message_type", None) == "private":
            return True

        # Check for legacy payload
        payload = getattr(request, "payload", None)
        if isinstance(payload, dict):
            if payload.get("legacy"):
                return True

    except Exception:
        # Any unexpected error should result in a safe False
        return False

    return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request.

    A Matrix request is typically a dictionary or an object that contains
    keys/attributes such as ``type`` (starting with ``m.``), ``content``,
    or ``msgtype``.  The function performs a best‑effort check and
    returns ``True`` if any of these indicators are present.  It
    gracefully handles unexpected input types and any runtime errors
    by returning ``False``.
    """
    try:
        if request is None:
            return False

        # If the request is a dictionary, look for typical Matrix keys
        if isinstance(request, dict):
            # Common Matrix request fields
            if "type" in request and isinstance(request["type"], str) and request["type"].startswith("m."):
                return True
            if "content" in request:
                return True
            if "msgtype" in request:
                return True

        # If the request is an object with attributes, inspect them
        for attr in ("type", "content", "msgtype"):
            if hasattr(request, attr):
                value = getattr(request, attr)
                # ``type`` should be a string starting with ``m.`` for Matrix
                if attr == "type":
                    if isinstance(value, str) and value.startswith("m."):
                        return True
                else:
                    # ``content`` or ``msgtype`` being non‑None is a hint
                    if value is not None:
                        return True

        # Fallback: if the request can be converted to a dict, try again
        if hasattr(request, "to_dict") and callable(request.to_dict):
            try:
                data = request.to_dict()
                if isinstance(data, dict):
                    return identify_request(data)
            except Exception:
                pass

        return False
    except Exception:
        # Any unexpected error results in a conservative False
        return False

def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    Accepts a datetime.datetime instance and returns an ISO 8601 string.
    Naive datetimes are assumed to be UTC and suffixed with 'Z'.
    Timezone-aware datetimes are returned in ISO 8601 format with offset.
    """
    try:
        if dt is None:
            raise ValueError("dt cannot be None")
        if not hasattr(dt, "strftime"):
            raise TypeError("dt must be a datetime instance")
        if getattr(dt, "tzinfo", None) is None:
            return dt.strftime("%Y-%m-%dT%H:%M:%SZ")
        return dt.isoformat()
    except Exception as exc:
        raise ValueError(f"Invalid datetime input: {exc}") from exc

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if not isinstance(tag, str):
        raise TypeError("tag must be a string")
    tag = tag.strip()
    if not tag:
        return False
    prev_char = ''
    for i, ch in enumerate(tag):
        if ch == '-':
            if i == 0 or i == len(tag) - 1:
                return False
            if prev_char == '-':
                return False
        elif 'a' <= ch <= 'z' or '0' <= ch <= '9':
            pass
        else:
            return False
        prev_char = ch
    return True

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    # Basic validation: node should be an Element-like object
    if node is None:
        raise TypeError("node cannot be None")
    if not hasattr(node, "tag") or not hasattr(node, "__iter__"):
        raise TypeError("node must be an XML element with iterable children")

    result = {}
    for child in node:
        tag = child.tag
        if tag in result:
            # If we already have a single element, convert to list
            existing = result[tag]
            if isinstance(existing, list):
                existing.append(child)
            else:
                result[tag] = [existing, child]
        else:
            result[tag] = child
    return result

def get_nodeinfo_well_known_document(url, document_path=None):
    """
    Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Basic validation
    if not isinstance(url, str) or not url:
        raise ValueError("url must be a non-empty string")
    if document_path is not None and not isinstance(document_path, str):
        raise ValueError("document_path must be a string if provided")

    # Default document path
    if document_path is None:
        document_path = "/.well-known/nodeinfo"

    # Ensure document_path starts with a slash
    if not document_path.startswith("/"):
        document_path = "/" + document_path

    # Build the full href
    base = url.rstrip("/")
    href = base + document_path

    # NodeInfo spec supports multiple schema versions; include 2.0 and 2.1
    links = [
        {
            "rel": "http://nodeinfo.diaspora.software/ns/schema/2.0",
            "href": href
        },
        {
            "rel": "http://nodeinfo.diaspora.software/ns/schema/2.1",
            "href": href
        }
    ]

    return {"links": links}

