def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    # Validate host input
    if not isinstance(host, str) or not host.strip():
        raise ValueError("host must be a non-empty string")

    # Normalize host (remove scheme if present)
    try:
        from urllib.parse import urlparse
        parsed = urlparse(host.strip())
        if parsed.scheme:
            host = parsed.netloc
        else:
            host = parsed.path
    except Exception:
        # If parsing fails, assume host is already a hostname
        host = host.strip()

    # Construct the well-known host-meta URL
    url = f"https://{host}/.well-known/host-meta"

    # Fetch the host-meta document
    try:
        import urllib.request
        import urllib.error
        with urllib.request.urlopen(url, timeout=10) as response:
            if response.status != 200:
                raise RuntimeError(f"Failed to retrieve host-meta: HTTP {response.status}")
            data = response.read()
    except urllib.error.URLError as e:
        raise RuntimeError(f"Error retrieving host-meta from {url}: {e}") from e
    except Exception as e:
        raise RuntimeError(f"Unexpected error retrieving host-meta from {url}: {e}") from e

    # Parse the XML
    try:
        import xml.etree.ElementTree as ET
        root = ET.fromstring(data)
    except ET.ParseError as e:
        raise ValueError(f"Failed to parse host-meta XML: {e}") from e

    # Attempt to return an XRD instance if the diaspora library is available
    try:
        from diaspora.xrd import XRD
        return XRD(root)
    except Exception:
        # Fallback: return the parsed ElementTree root
        return root

