@classmethod
    def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        # Define a minimal set of required fields for the spec.
        # Adjust this list according to the actual specification requirements.
        required_fields = ["name", "version"]

        # Custom exception class for validation errors
        class IRValidatorException(Exception):
            """Exception raised when the spec validation fails."""
            pass

        # Validate input
        if spec_content is None:
            raise IRValidatorException("Spec content is None.")
        if not isinstance(spec_content, str):
            raise IRValidatorException(
                f"Spec content must be a string, got {type(spec_content).__name__}."
            )
        if spec_content.strip() == "":
            raise IRValidatorException("Spec content is empty.")

        # Parse YAML content
        try:
            import yaml
        except ImportError as exc:
            raise IRValidatorException("PyYAML is required to parse spec content.") from exc

        try:
            data = yaml.safe_load(spec_content)
        except Exception as exc:
            raise IRValidatorException(f"Failed to parse YAML: {exc}") from exc

        # Ensure the parsed data is a dictionary
        if not isinstance(data, dict):
            raise IRValidatorException(
                f"Parsed spec must be a mapping (dict), got {type(data).__name__}."
            )

        # Check for required fields
        missing = [field for field in required_fields if field not in data]
        if missing:
            raise IRValidatorException(
                f"Missing required field(s) in spec: {', '.join(missing)}."
            )

        return data

@classmethod
def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    if yaml_file is None:
        raise ValueError("yaml_file must be provided")

    try:
        import yaml
    except ImportError as e:
        raise IRValidatorException("PyYAML is required to load YAML files") from e

    try:
        with open(yaml_file, "r", encoding="utf-8") as f:
            data = yaml.safe_load(f)
    except FileNotFoundError as e:
        raise IRValidatorException(f"File not found: {yaml_file}") from e
    except Exception as e:
        raise IRValidatorException(f"Error loading YAML file: {e}") from e

    if not isinstance(data, dict):
        raise IRValidatorException("YAML file does not contain a mapping at the top level")

    required_fields = getattr(cls, "REQUIRED_FIELDS", [])
    missing = [field for field in required_fields if field not in data]
    if missing:
        raise IRValidatorException(f"Missing required fields: {', '.join(missing)}")

    return data

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    # Ensure the instance has a 'spec' attribute
    if not hasattr(self, "spec"):
        raise AttributeError("Instance has no 'spec' attribute")

    spec = self.spec

    # If spec is None or empty, return an empty dict
    if spec is None:
        return {}

    # spec must be a mapping (dict-like)
    if not isinstance(spec, dict):
        raise TypeError(f"'spec' must be a dict, got {type(spec).__name__}")

    defaults = {}
    for key, value in spec.items():
        # If the spec entry is a dict, look for 'default' or 'default_factory'
        if isinstance(value, dict):
            if "default" in value:
                defaults[key] = value["default"]
            elif "default_factory" in value:
                factory = value["default_factory"]
                if callable(factory):
                    try:
                        defaults[key] = factory()
                    except Exception as exc:
                        raise ValueError(
                            f"Error calling default_factory for '{key}': {exc}"
                        ) from exc
                else:
                    raise TypeError(
                        f"default_factory for '{key}' must be callable, got {type(factory).__name__}"
                    )
            # If neither is present, skip this key
        else:
            # If the spec entry is not a dict, treat the value itself as the default
            defaults[key] = value

    return defaults

