def get_parser_option_specs(self, command_name):
    """
    Gets all the options for the specified command.

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # Validate input type
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")

    # Ensure the parser options dictionary exists
    parser_options = getattr(self, "_parser_options", None)
    if parser_options is None:
        raise AttributeError("The object does not have a '_parser_options' attribute")

    # Retrieve options for the given command
    try:
        options = parser_options[command_name]
    except KeyError:
        raise ValueError(f"Unknown command name: {command_name}") from None

    # Return a copy to prevent accidental modifications
    return list(options)

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    # Validate inputs
    if not isinstance(command_name, str) or not command_name:
        raise ValueError("command_name must be a non-empty string")
    if not isinstance(argument_name, str) or not argument_name:
        raise ValueError("argument_name must be a non-empty string")

    # Retrieve the command object
    try:
        command = self.commands[command_name]
    except (AttributeError, KeyError):
        raise KeyError(f"Command '{command_name}' not found")

    # Retrieve the option specification
    try:
        spec = command.options[argument_name]
    except (AttributeError, KeyError):
        raise KeyError(f"Option '{argument_name}' not found in command '{command_name}'")

    return spec

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    try:
        if args is None:
            return []

        # If args is a dictionary, consider keys with None or empty string values as silent
        if isinstance(args, dict):
            return [k for k, v in args.items() if v is None or v == '']

        # If args is a list or tuple, consider items that are None, empty strings, or start with an underscore as silent
        if isinstance(args, (list, tuple)):
            return [
                a for a in args
                if a is None or (isinstance(a, str) and (a == '' or a.startswith('_')))
            ]

        # If args is a single string, treat it as a silent argument only if it is empty or starts with an underscore
        if isinstance(args, str):
            return [args] if args == '' or args.startswith('_') else []

        # Unsupported type: return an empty list
        return []

    except Exception:
        # In case of any unexpected error, return an empty list
        return []

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    if args is None:
        raise TypeError("args cannot be None")
    if not isinstance(args, dict):
        raise TypeError("args must be a dict")
    required = getattr(self, "required_args", None)
    if required is None:
        raise AttributeError("required_args attribute not found")
    missing = [arg for arg in required if arg not in args]
    if missing:
        raise ValueError(f"Missing required arguments: {', '.join(missing)}")
    return True

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """
    List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    # Basic validation
    if not isinstance(options_spec, (list, tuple)):
        raise TypeError(f"options_spec must be a list or tuple, got {type(options_spec).__name__}")
    if not isinstance(args, dict):
        raise TypeError(f"args must be a dict, got {type(args).__name__}")

    def _evaluate(cond, local_args):
        """
        Evaluate a single condition expression against the provided arguments.
        The condition can be a callable, a boolean, or a string expression.
        """
        if cond is None:
            return False
        if isinstance(cond, bool):
            return cond
        if callable(cond):
            try:
                return bool(cond(local_args))
            except Exception:
                return False
        if isinstance(cond, str):
            # Strip whitespace to avoid accidental errors
            expr = cond.strip()
            if not expr:
                return False
            try:
                # Evaluate the expression with args as local variables
                return bool(eval(expr, {}, local_args))
            except Exception:
                return False
        # Unsupported condition type
        return False

    required_args = []
    for opt in options_spec:
        if not isinstance(opt, dict):
            continue
        cond = opt.get('required_when')
        if cond is None:
            continue
        # Support list/tuple of conditions combined with AND
        if isinstance(cond, (list, tuple)):
            matched = all(_evaluate(c, args) for c in cond)
        else:
            matched = _evaluate(cond, args)
        if matched:
            name = opt.get('name')
            if name:
                required_args.append(name)
    return required_args

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary of argument names to values")
    constraints = getattr(self, 'max_lengths', {})
    if not isinstance(constraints, dict):
        constraints = {}
    for key, value in args.items():
        if value is None:
            continue
        if not isinstance(value, str):
            continue
        max_len = constraints.get(key)
        if max_len is None:
            continue
        if not isinstance(max_len, int) or max_len < 0:
            continue
        if len(value) > max_len:
            raise ValueError(f"Argument '{key}' exceeds maximum length of {max_len} characters (got {len(value)}).")

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Ensure the instance has min and max attributes
    if not hasattr(self, "min") or not hasattr(self, "max"):
        raise AttributeError("Instance must have 'min' and 'max' attributes")
    min_val = self.min
    max_val = self.max

    # Validate that min and max are numeric and logically ordered
    try:
        min_val = float(min_val)
        max_val = float(max_val)
    except (TypeError, ValueError):
        raise TypeError("Instance 'min' and 'max' attributes must be numeric")

    if min_val > max_val:
        raise ValueError(f"Invalid bounds: min ({min_val}) is greater than max ({max_val})")

    # Validate args type
    if isinstance(args, dict):
        iterable = args.items()
    elif isinstance(args, (list, tuple)):
        iterable = enumerate(args)
    else:
        raise TypeError("args must be a dict, list, or tuple")

    # Iterate over arguments and validate each value
    for key, value in iterable:
        try:
            numeric_value = float(value)
        except (TypeError, ValueError):
            raise ValueError(f"Argument '{key}' value '{value}' is not numeric")

        if numeric_value < min_val or numeric_value > max_val:
            raise ValueError(
                f"Argument '{key}' value {numeric_value} is out of bounds "
                f"[{min_val}, {max_val}]"
            )

    return True

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                spec_option):
    """
    Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Basic validation of inputs
    if not isinstance(subcommand, str) or not subcommand:
        raise ValueError("subcommand must be a non-empty string")
    if not isinstance(type_name, str) or not type_name:
        raise ValueError("type_name must be a non-empty string")
    if not isinstance(option_name, str) or not option_name:
        raise ValueError("option_name must be a non-empty string")
    if not isinstance(spec_option, dict):
        raise ValueError("spec_option must be a dictionary")

    # Define a simple complex type holder
    class ComplexType:
        def __init__(self, subcommand, type_name, option_name, spec_option):
            self.subcommand = subcommand
            self.type_name = type_name
            self.option_name = option_name
            self.spec_option = spec_option

        def __repr__(self):
            return (f"<ComplexType type_name={self.type_name!r} "
                    f"subcommand={self.subcommand!r} "
                    f"option_name={self.option_name!r}>")

    try:
        return ComplexType(subcommand, type_name, option_name, spec_option)
    except Exception as exc:
        raise RuntimeError("Failed to create complex argument type") from exc

def get_nested_custom_and_control_args(self, args):
    """
    Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    if args is None:
        raise TypeError("args must be a list of argument strings")
    if not isinstance(args, list):
        raise TypeError("args must be a list, got %r" % type(args).__name__)

    control_args = {}
    nested_args = {}

    # Helper to process a key/value pair
    def _add_arg(key, value):
        key = key.lstrip('-')
        if key.startswith('control_'):
            control_args[key] = value
        else:
            # Treat everything else (including custom_) as nested
            nested_args[key] = value

    i = 0
    while i < len(args):
        arg = args[i]
        if not isinstance(arg, str):
            raise TypeError("argument at position %d is not a string: %r" % (i, arg))
        if arg.startswith('--'):
            # Long option
            if '=' in arg:
                key, val = arg.split('=', 1)
                _add_arg(key, val)
            else:
                key = arg
                # Check if next token is a value (doesn't start with '-')
                if i + 1 < len(args) and not args[i + 1].startswith('-'):
                    val = args[i + 1]
                    i += 1
                else:
                    val = True
                _add_arg(key, val)
        elif arg.startswith('-') and len(arg) > 1:
            # Short option (single dash). Treat similarly to long option
            if '=' in arg:
                key, val = arg.split('=', 1)
                _add_arg(key, val)
            else:
                key = arg
                if i + 1 < len(args) and not args[i + 1].startswith('-'):
                    val = args[i + 1]
                    i += 1
                else:
                    val = True
                _add_arg(key, val)
        else:
            # Positional argument or stray value; ignore or raise
            # We'll ignore it as it doesn't match expected pattern
            pass
        i += 1

    return control_args, nested_args

@staticmethod
    def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        :return: The updated dictionary
        """
        # Validate input types
        if not isinstance(vars_dict, dict):
            raise TypeError("vars_dict must be a dictionary")
        if extra_vars is None:
            return vars_dict
        if not isinstance(extra_vars, (list, tuple)):
            raise TypeError("extra_vars must be a list or tuple of strings")

        for item in extra_vars:
            # Skip non-string items
            if not isinstance(item, str):
                continue
            # Only process items containing '='
            if '=' not in item:
                continue
            key, value = item.split('=', 1)
            key = key.strip()
            value = value.strip()
            # If key is empty, skip
            if not key:
                continue
            # Update the dictionary
            vars_dict[key] = value

        return vars_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict in place.
    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of arguments
    """
    def _cast_value(v):
        # If already a non-string type, return as is
        if not isinstance(v, str):
            return v
        s = v.strip()
        # Handle boolean
        if s.lower() == "true":
            return True
        if s.lower() == "false":
            return False
        # Handle None
        if s.lower() == "none":
            return None
        # Handle comma-separated lists
        if "," in s:
            parts = [p.strip() for p in s.split(",")]
            return [_cast_value(p) for p in parts]
        # Handle integer
        if s.isdigit() or (s.startswith("-") and s[1:].isdigit()):
            try:
                return int(s)
            except ValueError:
                pass
        # Handle float
        try:
            return float(s)
        except ValueError:
            pass
        # Fallback: return original string
        return s

    # Iterate over a copy of keys to avoid runtime errors when modifying dict
    for key in list(values_dict.keys()):
        values_dict[key] = _cast_value(values_dict[key])

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    from pathlib import Path
    import json

    # Helper to load YAML if available
    def _load_yaml(file_path):
        try:
            import yaml
        except ImportError:
            raise ValueError("YAML support is not available. Install PyYAML to load .yaml files.")
        with open(file_path, 'r', encoding='utf-8') as f:
            return yaml.safe_load(f)

    def _flatten(d, parent_key='', sep='.'):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    plugin_path = Path(plugin_dir)
    if not plugin_path.is_dir():
        raise FileNotFoundError(f"Plugin directory '{plugin_dir}' does not exist or is not a directory.")

    # Determine spec file: prefer JSON, fallback to YAML
    spec_file = None
    json_path = plugin_path / 'plugin.json'
    yaml_path = plugin_path / 'plugin.yaml'
    yml_path = plugin_path / 'plugin.yml'

    if json_path.is_file():
        spec_file = json_path
        loader = lambda p: json.load(open(p, 'r', encoding='utf-8'))
    elif yaml_path.is_file():
        spec_file = yaml_path
        loader = _load_yaml
    elif yml_path.is_file():
        spec_file = yml_path
        loader = _load_yaml
    else:
        raise FileNotFoundError("No plugin spec file found (plugin.json, plugin.yaml, or plugin.yml).")

    try:
        spec_data = loader(spec_file)
    except Exception as e:
        raise ValueError(f"Failed to load plugin spec from '{spec_file}': {e}")

    if not isinstance(spec_data, dict):
        raise ValueError(f"Plugin spec must be a dictionary, got {type(spec_data).__name__}")

    return _flatten(spec_data)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    config_env_var = "CONFIG_PATH"
    try:
        # If the variable is not set or empty, set it to a default path
        if not os.environ.get(config_env_var):
            default_path = os.path.join(os.getcwd(), "config.yaml")
            os.environ[config_env_var] = default_path
    except Exception as exc:
        raise RuntimeError(f"Failed to inject config environment variable: {exc}") from exc
